window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-118"]=[{"id":"set2-0OWZN0Jj","fingerprint":"aaec8b66370e3019","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la stadiul I de dezvoltare al dintelui temporar (dinte temporar tânăr)?","options":[{"id":"A","text":"În acest stadiu, camera pulpară este de dimensiuni reduse."},{"id":"B","text":"Rădăcina își finalizează formarea complet în momentul erupției în cavitatea bucală."},{"id":"C","text":"Acest stadiu de dezvoltare începe în viața postnatală."},{"id":"D","text":"Erupția dinților temporari are loc între 6-30 luni."},{"id":"E","text":"Este perioada de creștere și dezvoltare, până la edificarea rădăcinii."}],"correct":["D","E"],"pages":[388],"source":"set-2"},{"id":"set2-BzwBBpuL","fingerprint":"1a93c3f963cd0fea","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce caracteristici morfologice sunt specifice dintelui temporar matur (stadiul II)?","options":[{"id":"A","text":"Canaliculele dentinare sunt înguste, iar canalele radiculare sunt largi."},{"id":"B","text":"Comunicarea pulpo-parodontală se realizează exclusiv printr-un singur canal apical."},{"id":"C","text":"Camera pulpară este mare, comparativ cu grosimea țesuturilor dure dentare."},{"id":"D","text":"Pulpa dentară este voluminoasă și bine vascularizată, iar coarnele pulpare sunt situate superficial."},{"id":"E","text":"Rădăcinile sunt robuste, convergente și nu au legătură cu mugurii dinților permanenți."}],"correct":["C","D"],"pages":[388],"source":"set-2"},{"id":"set2-lUegXDr8","fingerprint":"00358ee13c4d1a6f","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce modificări apar în stadiul III al dintelui temporar, cel cu rădăcina în resorbție?","options":[{"id":"A","text":"Potențialul defensiv și reparator al pulpei crește semnificativ."},{"id":"B","text":"Rădăcina se alungește, iar orificiul apical se îngustează."},{"id":"C","text":"Apar modificări degenerative fibroase și depuneri calcare intrapulpare."},{"id":"D","text":"Comunicarea pulpo-parodontală se reduce din cauza proceselor de apoziție osoasă."},{"id":"E","text":"Pulpa suferă un proces de involuție, cu diminuarea elementului celular."}],"correct":["C","E"],"pages":[388],"source":"set-2"},{"id":"set2-6BzxHzVd","fingerprint":"c2104590450f0432","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații referitoare la cronologia rizalizei dinților temporari este corectă?","options":[{"id":"A","text":"Procesul de resorbție radiculară începe simultan pentru toate grupele de dinți temporari."},{"id":"B","text":"Rizaliza începe în jurul vârstei de 8 ani pentru caninii temporari."},{"id":"C","text":"Rizaliza începe în jurul vârstei de 6-7 ani pentru molarii temporari."},{"id":"D","text":"Rizaliza începe în jurul vârstei de 4-5 ani pentru incisivii temporari."},{"id":"E","text":"Rizaliza debutează prima dată la canini, apoi la molari și la final la incisivi."}],"correct":["B","C","D"],"pages":[388],"source":"set-2"},{"id":"set2-ILW1fGDY","fingerprint":"507b24b43023b85c","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt consecințele particularităților morfologice și structurale ale dinților temporari în ceea ce privește leziunile odontale?","options":[{"id":"A","text":"Capacitate reparatorie crescută a pulpei dentare."},{"id":"B","text":"Evoluția lentă a cariei dentare."},{"id":"C","text":"Simptomatologia specifică se explică printr-o inervație mai bogată comparativ cu dinții permanenți."},{"id":"D","text":"Prezența cariilor cronice dovedește capacitatea de formare a dentinei de reacție."},{"id":"E","text":"Expunerea la deschiderea accidentală a camerei pulpare."}],"correct":["D","E"],"pages":[388],"source":"set-2"},{"id":"set2-o-0qjn-e","fingerprint":"4b3abdeafc515ca2","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt factorii importanți care asigură protecția împotriva traumatismelor ocluzale la dinții temporari?","options":[{"id":"A","text":"Suprafața de contact interdentară."},{"id":"B","text":"Zona papilară bine reprezentată."},{"id":"C","text":"Depunerea de dentină de reacție."},{"id":"D","text":"Procesele de abrazie fiziologică."},{"id":"E","text":"Forma globuloasă a coroanelor."}],"correct":["A","B","E"],"pages":[389],"source":"set-2"},{"id":"set2-0Uc2kckx","fingerprint":"16bd4135229d4c0d","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Prin ce se caracterizează caria complicată a dinților temporari?","options":[{"id":"A","text":"Are o evoluție lentă, de aproximativ 1-2 ani, permițând depunerea de dentină de reacție."},{"id":"B","text":"Afectează smalțul și într-o anumită proporție dentina, fără a determina apariția simptomatologiei pulpare."},{"id":"C","text":"Interesează smalțul până la limita amelo-dentinară."},{"id":"D","text":"Afectează smalțul și extensiv dentina, cu apariția simptomatologiei pulpare."},{"id":"E","text":"Este o leziune odontală care s-a oprit în evoluție datorită apariției condițiilor de autocurățire."}],"correct":["D"],"pages":[389],"source":"set-2"},{"id":"set2-fuD4XfoB","fingerprint":"2ed06c65c7777b4e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce suprafețe dentare sunt interesate în cazul unei cavități de clasa a IV-a conform clasificării Black la dinții temporari?","options":[{"id":"A","text":"Zona cervicală a coroanelor dentare."},{"id":"B","text":"Suprafețele proximale ale incisivilor și caninilor, fără interesarea unghiului incizal."},{"id":"C","text":"Suprafețele proximale ale molarilor temporari."},{"id":"D","text":"Suprafața ocluzală a molarilor temporari."},{"id":"E","text":"Suprafețele proximale ale incisivilor și caninilor, cu interesarea unghiului incizal."}],"correct":["E"],"pages":[389],"source":"set-2"},{"id":"set2-8_iVPNrt","fingerprint":"15862f661aa31dbc","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce clasă de cavități, conform clasificării lui Black, este mai rar diagnosticată la dinții temporari din cauza abraziei fiziologice?","options":[{"id":"A","text":"Clasa a II-a"},{"id":"B","text":"Clasa a V-a"},{"id":"C","text":"Clasa a VI-a"},{"id":"D","text":"Clasa a IV-a"},{"id":"E","text":"Clasa I"}],"correct":["C"],"pages":[389],"source":"set-2"},{"id":"set2-9eZBrkBu","fingerprint":"5b73a99ad140824e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect caria acută a dinților temporari?","options":[{"id":"A","text":"Pulpa dentară are timp să depună cantități mari de dentină de reacție."},{"id":"B","text":"Poate deveni o carie penetrantă, complicată, în 1-2 luni."},{"id":"C","text":"Are o evoluție rapidă spre profunzime."},{"id":"D","text":"Prezintă o deschidere mare în suprafață, ceea ce favorizează autocurățirea."},{"id":"E","text":"Evoluează lent, pe parcursul a 1-2 ani, până la deschiderea camerei pulpare."}],"correct":["B","C"],"pages":[389],"source":"set-2"},{"id":"set2-FkwGXwMg","fingerprint":"149a5036d465be05","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce caracteristici sunt specifice cariei cronice a dinților temporari?","options":[{"id":"A","text":"Evoluție rapidă spre profunzime, în 1-2 luni."},{"id":"B","text":"Evoluția sa este lentă, de aproximativ 1-2 ani de la debut până la deschiderea camerei pulpare."},{"id":"C","text":"Prezintă o deschidere mai mare în suprafață și o extindere mai redusă în profunzime."},{"id":"D","text":"Dentina afectată de pe peretele pulpar este dură și de culoare brun-negru."},{"id":"E","text":"Pulpa nu reușește să depună în același ritm dentină de reacție."}],"correct":["B","C","D"],"pages":[389],"source":"set-2"},{"id":"set2-3wYav9eP","fingerprint":"1ed972713e1fb168","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la caria oprită în evoluție?","options":[{"id":"A","text":"Suprafața de smalț afectată este moale și de culoare alb-gălbuie."},{"id":"B","text":"Oprirea evoluției este favorizată de extracția dintelui vecin."},{"id":"C","text":"Procesele de demineralizare le înlocuiesc pe cele de remineralizare."},{"id":"D","text":"Apare frecvent pe suprafețele proximale ale dinților."},{"id":"E","text":"La origine, a fost o carie acută."}],"correct":["B","D","E"],"pages":[389],"source":"set-2"},{"id":"set2-Iikwq9LZ","fingerprint":"3f96bd3947325a7e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Conform clasificării în funcție de profunzimea leziunii, cum este definită caria profundă a dinților temporari?","options":[{"id":"A","text":"Este caria care interesează smalțul până la limita amelo-dentinară."},{"id":"B","text":"Procesul carios interesează și dentina și, netratat, va determina apariția cariei complicate."},{"id":"C","text":"Este o carie acută care poate deveni penetrantă în 1-2 luni."},{"id":"D","text":"Este o carie localizată în treimea cervicală a coroanei."},{"id":"E","text":"Este caria care a afectat extensiv dentina, cu apariția simptomatologiei pulpare."}],"correct":["B"],"pages":[389],"source":"set-2"},{"id":"set2-7MoIQgD2","fingerprint":"3595531efb3f2745","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect caria circulară la dinții temporari?","options":[{"id":"A","text":"Debutează clinic ca o pigmentație pe fața vestibulară, la nivelul coletului dentar."},{"id":"B","text":"Afectează cu predilecție incisivii inferiori, protejând dinții superiori."},{"id":"C","text":"Se extinde cu precădere în profunzime, având o afectare redusă în suprafață."},{"id":"D","text":"Progresia leziunilor este accelerată de activitatea bacteriilor acidogene."},{"id":"E","text":"Apare frecvent la copiii care adorm cu biberonul conținând băuturi îndulcite."}],"correct":["A","D","E"],"pages":[390],"source":"set-2"},{"id":"set2-C66joDrq","fingerprint":"1c7a7984015d5602","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce afecțiune este definită ca mortificarea septică a țesuturilor pulpare?","options":[{"id":"A","text":"Pulpita acută seroasă"},{"id":"B","text":"Parodontita apicală cronică"},{"id":"C","text":"Necroza pulpară"},{"id":"D","text":"Gangrena pulpară"},{"id":"E","text":"Pulpita cronică ulceroasă"}],"correct":["D"],"pages":[390],"source":"set-2"},{"id":"set2-QRBGdS76","fingerprint":"5031b6299294bc85","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele criterii sunt utilizate în clasificarea pulpitelor dinților temporari în funcție de evoluție?","options":[{"id":"A","text":"Asimptomatice"},{"id":"B","text":"Cu camera pulpară deschisă"},{"id":"C","text":"Acute"},{"id":"D","text":"Purulente"},{"id":"E","text":"Ireversibile"}],"correct":["A","C","E"],"pages":[390],"source":"set-2"},{"id":"set2-OeTuGdbl","fingerprint":"b421401a9bf997e3","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce grup de dinți este cel mai rar afectat în cazul cariei circulare?","options":[{"id":"A","text":"Molarii inferiori"},{"id":"B","text":"Molarii primi superiori"},{"id":"C","text":"Caninii inferiori"},{"id":"D","text":"Incisivii superiori"},{"id":"E","text":"Incisivii inferiori"}],"correct":["E"],"pages":[390],"source":"set-2"},{"id":"set2-R9rYNqd8","fingerprint":"8f71b65c054e1d9e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele entități clinice sunt forme de pulpită cronică?","options":[{"id":"A","text":"Pulpita acută seroasă parțială"},{"id":"B","text":"Pulpita cronică ulceroasă"},{"id":"C","text":"Gangrena pulpară simplă"},{"id":"D","text":"Pulpita acută purulentă totală"},{"id":"E","text":"Pulpita cronică granulomatoasă (polipoasă)"}],"correct":["B","E"],"pages":[390],"source":"set-2"},{"id":"set2-XijjIR9u","fingerprint":"1637243310a36903","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Prin ce se diferențiază gangrena pulpară complicată de cea simplă?","options":[{"id":"A","text":"Gangrena complicată implică afectarea țesuturilor parodontale periapicale."},{"id":"B","text":"Gangrena complicată este simptomatică, în timp ce cea simplă este asimptomatică."},{"id":"C","text":"Gangrena simplă nu afectează țesuturile parodontale."},{"id":"D","text":"Gangrena complicată este o mortificare aseptică, iar cea simplă este septică."},{"id":"E","text":"Gangrena simplă evoluează întotdeauna spre parodontită apicală acută."}],"correct":["A","C"],"pages":[390],"source":"set-2"},{"id":"set2-MZtnzqWp","fingerprint":"138e23a244a8d283","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt simptomele subiective ce pot fi asociate cu caria simplă la copii?","options":[{"id":"A","text":"Sensibilitate la ingestia de dulciuri."},{"id":"B","text":"Sensibilitate relatată de pacient la contactul cu agenți termici și chimici."},{"id":"C","text":"Durere constantă, cu un tipar clasic."},{"id":"D","text":"Durere spontană, care apare fără un stimul declanșator."},{"id":"E","text":"Refuzul alimentației în cazul leziunilor odontale multiple și profunde."}],"correct":["A","B","E"],"pages":[391],"source":"set-2"},{"id":"set2-xYi7n-Ly","fingerprint":"356052b0dfd8156a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce semne obiective pot fi observate la inspecția unui dinte cu carie simplă?","options":[{"id":"A","text":"Colorații brun-negricioase la nivelul fisurilor sau fosetelor."},{"id":"B","text":"Rezultate pozitive la percuția axială."},{"id":"C","text":"Creasta marginală subminată."},{"id":"D","text":"Transluciditate crescută a smalțului."},{"id":"E","text":"Prezența unei pete albe cretoase."}],"correct":["A","C","E"],"pages":[391],"source":"set-2"},{"id":"set2-Xg5wTvpr","fingerprint":"7cf3ca98c55e2a4f","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce caracteristică diferențiază caria acută de cea cronică la palparea cu sonda dentară?","options":[{"id":"A","text":"Doar în caria acută se poate îndepărta dentina ramolită cu o linguriță Black."},{"id":"B","text":"În caria acută, sonda pătrunde cu ușurință în dentina ramolită."},{"id":"C","text":"În caria cronică, sonda nu poate agăța în discontinuități."},{"id":"D","text":"În caria acută, țesuturile dentinare sunt dure și rugoase."},{"id":"E","text":"În caria cronică, se observă o fisură în stratul de cement."}],"correct":["B"],"pages":[391],"source":"set-2"},{"id":"set2-uN8TzzCH","fingerprint":"39cae0bdb570aa04","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce indică rezultatele testului de percuție în contextul diagnosticării afecțiunilor dentare la copil?","options":[{"id":"A","text":"Percuția axială pozitivă poate indica o patologie periapicală."},{"id":"B","text":"Percuția paraaxială pozitivă poate sugera o leziune de cauză parodontală."},{"id":"C","text":"Percuția este negativă în cazul cariei simple a dinților temporari."},{"id":"D","text":"O percuție paraaxială negativă exclude prezența unei pulpite seroase."},{"id":"E","text":"Rezultatele sunt considerate foarte precise la pacienții copii."}],"correct":["A","B","C"],"pages":[391],"source":"set-2"},{"id":"set2-YuUZjrlb","fingerprint":"58ad917e87ec0d65","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care afirmație descrie corect utilizarea probelor termice la copii pentru diagnosticarea afecțiunilor pulpare?","options":[{"id":"A","text":"Sunt considerate teste concludente datorită colaborării excelente a pacienților tineri."},{"id":"B","text":"Testele trebuie aplicate cu presiune fermă pentru a obține un răspuns clar."},{"id":"C","text":"Stimulii calzi, precum un baton de gutapercha încălzit, se aplică în treimea cervicală a dintelui."},{"id":"D","text":"Factorii fizici utilizați în aceste teste nu pot declanșa o suferință pulpară."},{"id":"E","text":"Se aplică exclusiv stimuli reci, precum spray-ul cu clorură de etil."}],"correct":["C"],"pages":[391],"source":"set-2"},{"id":"set2-sdmixcXT","fingerprint":"6e67365b752847fe","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce informații relevante pot fi obținute prin examenul radiologic în diagnosticul cariei dentare la copii?","options":[{"id":"A","text":"Determinarea gradului de rizaliză a dintelui temporar."},{"id":"B","text":"Aprecierea profunzimii proceselor carioase și a proximității față de camera pulpară."},{"id":"C","text":"Evaluarea vitalității pulpare."},{"id":"D","text":"Evidențierea leziunilor carioase proximale."},{"id":"E","text":"Identificarea consistenței dentinei, dacă este ramolită sau dură."}],"correct":["A","B","D"],"pages":[391],"source":"set-2"},{"id":"set2-jzF4LHfn","fingerprint":"e9a34367be30c9cc","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care este metoda de elecție pentru diagnosticarea unei leziuni carioase proximale care nu este evidentă la inspecția clinică?","options":[{"id":"A","text":"Palparea meticuloasă cu sonda dentară la nivelul crestei marginale."},{"id":"B","text":"Aplicarea probelor termice la nivelul papilei interdentare."},{"id":"C","text":"Radiografia dentară retroalveolară sau bite-wing."},{"id":"D","text":"Inspecția modificărilor de culoare sub creasta marginală."},{"id":"E","text":"Testarea prin percuție paraaxială."}],"correct":["C"],"pages":[391],"source":"set-2"},{"id":"set2-eONk0H7I","fingerprint":"ac152a92297b5bd1","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Pentru a stabili un diagnostic corect, în special în cazul cariilor cu localizare ocluzală și proximală, ce se recomandă a fi asociat?","options":[{"id":"A","text":"Inspecția vizuală și testele de percuție axială."},{"id":"B","text":"Metodele vizuale și tactile (inspecție și palpare) cu examenul radiologic."},{"id":"C","text":"Doar examenul radiologic de tip ortopantomografie (OPT)."},{"id":"D","text":"Palparea cu sonda și percuția cu mânerul oglinzii."},{"id":"E","text":"Examenul radiologic (bite-wing sau OPT) și probele termice."}],"correct":["B"],"pages":[391],"source":"set-2"},{"id":"set2-ft6YSr9H","fingerprint":"84934da4a9ea9c61","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afecțiuni trebuie luate în considerare în diagnosticul diferențial al cariei simple a dinților temporari?","options":[{"id":"A","text":"Pulpita cronică cu cameră pulpară închisă, care poate evolua asimptomatic."},{"id":"B","text":"Abcesul periapical acut."},{"id":"C","text":"Pulpita acută seroasă totală."},{"id":"D","text":"Displaziile dentare, în special pentru caria cronică și cea incipientă."},{"id":"E","text":"Necroza și gangrena pulpară, chiar și cu un proces carios aparent nepenetrant."}],"correct":["A","D","E"],"pages":[392],"source":"set-2"},{"id":"set2-6AX75T9_","fingerprint":"bc4f6050d20c1a5b","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt factorii esențiali pentru asigurarea unui prognostic favorabil pe termen lung în cazul cariei simple la dinții temporari?","options":[{"id":"A","text":"Efectuarea de controale periodice la intervale de 3-6 luni."},{"id":"B","text":"Diagnosticul precoce al formelor de debut ale cariei dentare."},{"id":"C","text":"Tratamentul exclusiv al leziunilor carioase profunde."},{"id":"D","text":"Complianța pacientului și a familiei la planul de tratament și profilaxie."},{"id":"E","text":"Amânarea tratamentului până la apropierea momentului exfolierii dintelui."}],"correct":["A","B","D"],"pages":[392],"source":"set-2"},{"id":"set2-NWZuSvOs","fingerprint":"0840d7050ea73daf","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"De ce elemente depinde conduita terapeutică în tratamentul cariei simple a dinților temporari?","options":[{"id":"A","text":"Costul intervenției terapeutice."},{"id":"B","text":"Tipul materialului de obturație preferat de părinți."},{"id":"C","text":"Criteriile topografice la nivelul arcadei dentare."},{"id":"D","text":"Vârsta cronologică și vârsta dentară a pacientului."},{"id":"E","text":"Particularitățile morfo-structurale specifice dinților temporari."}],"correct":["C","D","E"],"pages":[392],"source":"set-2"},{"id":"set2-EDiVMhXg","fingerprint":"8faf595388d8bc6e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Conform criteriilor topografice, care este atitudinea recomandată în tratamentul leziunilor carioase la nivelul zonei de sprijin la un copil de 9 ani?","options":[{"id":"A","text":"Se tratează cu prioritate molarul doi și caninul temporar superior."},{"id":"B","text":"Se tratează toată zona de sprijin, fără excepție."},{"id":"C","text":"Se amână orice tratament, deoarece dinții se vor exfolia curând."},{"id":"D","text":"Se tratează exclusiv caninul temporar inferior și primul molar."},{"id":"E","text":"Se tratează doar leziunile de la nivelul grupului frontal."}],"correct":["A"],"pages":[392],"source":"set-2"},{"id":"set2-1LjjO_op","fingerprint":"886cfda2aa57e607","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele reprezintă dificultăți specifice în tratamentul cariei simple la dinții temporari?","options":[{"id":"A","text":"Dimensiunile reduse ale leziunilor carioase."},{"id":"B","text":"Grosimea redusă a țesuturilor dure dentare."},{"id":"C","text":"Volumul mare al camerei pulpare și situarea superficială a coarnelor pulpare."},{"id":"D","text":"Particularitățile psiho-somatice ale copilului."},{"id":"E","text":"Gradul înalt de mineralizare al smalțului, care îngreunează prepararea."}],"correct":["B","C","D"],"pages":[392],"source":"set-2"},{"id":"set2-55Q6Ibnc","fingerprint":"2826f26c55b287a5","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce particularități prezintă timpii de preparare a cavităților la dinții temporari?","options":[{"id":"A","text":"Timpul de extensie preventivă este complet eliminat din protocol."},{"id":"B","text":"Ordinea timpilor de preparare propusă de Black este inversată."},{"id":"C","text":"Bizotarea marginilor cavității este obligatorie pentru a crește retenția."},{"id":"D","text":"Curățarea cavității se realizează după asigurarea retenției."},{"id":"E","text":"Retenția și rezistența se obțin prin extensia cavității în suprafață, nu în profunzime."}],"correct":["E"],"pages":[392],"source":"set-2"},{"id":"set2-9LOwUbf_","fingerprint":"67d936fc9d094a3c","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În cazul preparării unei cavități de clasa I la un molar temporar, care dintre următoarele afirmații este corectă?","options":[{"id":"A","text":"Extensia cavității se face obligatoriu în profunzime pentru a asigura rezistența."},{"id":"B","text":"Se pot realiza două cavități ocluzale distincte dacă creasta oblică de smalț este suficient de rezistentă."},{"id":"C","text":"Prepararea este identică cu cea pentru un molar permanent, fără nicio particularitate."},{"id":"D","text":"Creasta oblică de smalț trebuie întotdeauna îndepărtată pentru a unifica preparația."},{"id":"E","text":"Doar fosetele centrale trebuie incluse în conturul cavității, cele accesorii fiind ignorate."}],"correct":["B"],"pages":[392],"source":"set-2"},{"id":"set2-S28c5ejZ","fingerprint":"5f38c3c69ad7fee7","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la prepararea unei cavități de clasa a II-a pe un dinte temporar?","options":[{"id":"A","text":"Se pot utiliza coroane pedodontice preformate în cazul cavităților cu un design simplu."},{"id":"B","text":"Poziția superficială a coarnelor pulpare scade riscul de deschidere accidentală a camerei pulpare."},{"id":"C","text":"Realizarea ismului face parte din secvența de preparare a cavității."},{"id":"D","text":"Pregătirea unui prag gingival este o etapă caracteristică."},{"id":"E","text":"Retenția ocluzală trebuie să fie cât mai extinsă posibil pentru a garanta durabilitatea, chiar dacă reduce rezistența dintelui."}],"correct":["C","D"],"pages":[393],"source":"set-2"},{"id":"set2-L-102H4s","fingerprint":"72609cc2d0d6e512","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce abordare terapeutică este recomandată în cazul cariilor superficiale care afectează incisivii temporari?","options":[{"id":"A","text":"Prepararea unor casete simple cu retenții palatinale extinse."},{"id":"B","text":"Deschiderea cavității și obturarea cu materiale compozite pentru o estetică superioară."},{"id":"C","text":"Șlefuirea suprafeței proximale, urmată de fluorizare."},{"id":"D","text":"Crearea unei cavități de 1,5-2mm adâncime care să includă toate zonele demineralizate."},{"id":"E","text":"Aplicarea sistematică a unei coroane pedodontice preformate."}],"correct":["C"],"pages":[393],"source":"set-2"},{"id":"set2-D3zseEfo","fingerprint":"c3b9ee587efbff78","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt avantajele care justifică utilizarea preferențială a cimenturilor glassionomer în restaurarea dinților temporari?","options":[{"id":"A","text":"Au proprietăți bio-active."},{"id":"B","text":"Sunt indicate doar pacienților cu o igienă oro-dentară foarte bună."},{"id":"C","text":"Permit mici imperfecțiuni tehnice atunci când izolarea se face cu rulouri de bumbac."},{"id":"D","text":"Necesită respectarea riguroasă a criteriilor de izolare, fără excepție."},{"id":"E","text":"Sunt recomandate pentru pacienții care prezintă un risc carios ridicat."}],"correct":["A","C","E"],"pages":[393],"source":"set-2"},{"id":"set2-JWu8a6Xc","fingerprint":"2b5355a7835cad4a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce principii trebuie respectate în timpul tratamentului unei carii simple superficiale la un pacient copil?","options":[{"id":"A","text":"Controlul îndepărtării țesuturilor afectate se bazează exclusiv pe inspecția vizuală și tactilă a medicului."},{"id":"B","text":"Pentru toaleta cavității se utilizează substanțe iritante pentru o dezinfecție eficientă."},{"id":"C","text":"Îndepărtarea procesului carios se realizează cu freze de turbină, diamantate, pentru a reduce vibrațiile și durata intervenției."},{"id":"D","text":"Izolarea cu sistemul de digă este obligatorie, indiferent de complianța pacientului."},{"id":"E","text":"Uscarea cavității trebuie să fie una intensă pentru a asigura aderența maximă a materialului de obturație."}],"correct":["C"],"pages":[393],"source":"set-2"},{"id":"set2-hQn_CHsd","fingerprint":"d4a7b42054e6959b","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care dintre următoarele reguli de preparare a cavităților este corectă?","options":[{"id":"A","text":"În cavitățile de clasa V, adâncimea preparării nu trebuie să depășească 1,5-2mm."},{"id":"B","text":"Apropierea de gingie în cazul cavităților de clasa V simplifică izolarea și aplicarea materialului de obturație."},{"id":"C","text":"În prepararea unei cavități de clasa I, se vor include în contur doar fosetele și fisurile cele mai profunde."},{"id":"D","text":"În cavitățile de clasa I, creasta oblică de smalț se îndepărtează sistematic pentru a crea o singură cavitate."},{"id":"E","text":"În cavitățile de clasa V, se includ în contur doar zonele cu leziuni cavitare, ignorând zonele decalcifiate adiacente."}],"correct":["A"],"pages":[393],"source":"set-2"},{"id":"set2-c8PQa1Ze","fingerprint":"2f3fc061d38a2f7a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce opțiuni terapeutice sunt menționate pentru leziunile carioase localizate pe caninii temporari?","options":[{"id":"A","text":"Prepararea unor casete simple, fără retenții suplimentare."},{"id":"B","text":"Realizarea unei retenții pe suprafața orală, dacă stadiul evolutiv și morfologia coronară o permit."},{"id":"C","text":"Șlefuirea suprafeței proximale urmată de fluorizare, ca abordare standard."},{"id":"D","text":"Doar deschiderea și curățarea cavității, urmată de obturație provizorie."},{"id":"E","text":"Aplicarea unei coroane pedodontice preformate."}],"correct":["B","E"],"pages":[393],"source":"set-2"},{"id":"set2-VluqwZVT","fingerprint":"eb5f355888af61f1","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele reprezintă etape în tratamentul cariei simple profunde la dinții temporari?","options":[{"id":"A","text":"Finisarea obturației cu freze diamantate fine"},{"id":"B","text":"Toaleta cavității"},{"id":"C","text":"Tratamentul plăgii dentinare"},{"id":"D","text":"Îndepărtarea țesuturilor dentare alterate"},{"id":"E","text":"Restaurarea morfologiei coronare"}],"correct":["B","C","D","E"],"pages":[394],"source":"set-2"},{"id":"set2-94b4Iax1","fingerprint":"b3ea30d2e3a1da7e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În ce situație clinică este indicat coafajul indirect în tratamentul unei carii profunde la un dinte temporar?","options":[{"id":"A","text":"Când pe baza cavității există o zonă extinsă de dentină moale și dintele a fost simptomatic."},{"id":"B","text":"Când dentina de pe baza cavității este dură, dar se suspectează afectarea integrității pulpare."},{"id":"C","text":"Când există o deschidere accidentală, limitată, a camerei pulpare în timpul preparării cavității."},{"id":"D","text":"Când dentina de pe baza cavității este dură, de culoare normală sau pigmentată, iar dintele se află în stadiul 1 sau 2."},{"id":"E","text":"Când se utilizează exclusiv cimentul pe bază de zinc-oxid-eugenat (ZOE) ca material de restaurare finală."}],"correct":["D"],"pages":[394],"source":"set-2"},{"id":"set2-FAiP-Kre","fingerprint":"b2e79f419134a301","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce condiții trebuie îndeplinite pentru a realiza un coafaj direct în cazul unei deschideri a camerei pulpare la un dinte temporar?","options":[{"id":"A","text":"Condițiile de izolare să fie respectate."},{"id":"B","text":"Dintele temporar să se afle în stadiul 1 sau la debutul stadiului 2."},{"id":"C","text":"Zona de deschidere să fie limitată."},{"id":"D","text":"Dintele temporar să fi fost simptomatic înainte de prepararea cavității."},{"id":"E","text":"Deschiderea să fie înconjurată de țesut dentinar neafectat."}],"correct":["A","B","C","E"],"pages":[394],"source":"set-2"},{"id":"set2-JpegrdrO","fingerprint":"69c7fe8e2ec2df46","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele materiale dentare sunt menționate ca fiind utilizate în tratamentul plăgii dentinare?","options":[{"id":"A","text":"Biodentine"},{"id":"B","text":"Cimentul pe bază de zinc-oxid-eugenat (ZOE)"},{"id":"C","text":"Hidroxidul de calciu"},{"id":"D","text":"Incrustații pedodontice"},{"id":"E","text":"Discuri de finisare"}],"correct":["A","B","C"],"pages":[394],"source":"set-2"},{"id":"set2-AaNERgtg","fingerprint":"8238d5e4a48ac18e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt avantajele utilizării incrustațiilor pentru restaurarea molarilor temporari cu carii profunde?","options":[{"id":"A","text":"Realizarea punctelor de contact."},{"id":"B","text":"Evitarea etapelor de laborator."},{"id":"C","text":"Costul redus al tratamentului."},{"id":"D","text":"Reducerea pericolului de fracturare la nivelul istmului."},{"id":"E","text":"Evitarea pericolului lezării pulpei."}],"correct":["A","D","E"],"pages":[394],"source":"set-2"},{"id":"set2-Zlz4FQ8n","fingerprint":"d122976773ebd72e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce dezavantaje prezintă utilizarea incrustațiilor în tratamentul dinților temporari?","options":[{"id":"A","text":"Refacerea deficitară a punctelor de contact."},{"id":"B","text":"Necesită șlefuiri extensive ale țesutului dentar."},{"id":"C","text":"Solicită răbdarea copilului în timpul amprentării și adaptării."},{"id":"D","text":"Necesită realizarea unor etape de laborator."},{"id":"E","text":"Nu pot fi aplicate pe scară largă."}],"correct":["C","D","E"],"pages":[394],"source":"set-2"},{"id":"set2-R7UjB797","fingerprint":"1510299664c169d1","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce beneficii oferă utilizarea coroanelor pedodontice preformate în refacerea morfologiei coronare?","options":[{"id":"A","text":"Asigură refacerea funcțiilor aparatului dento-maxilar."},{"id":"B","text":"Refac punctele de contact și dimensiunea verticală."},{"id":"C","text":"Necesită șlefuiri minime pentru adaptare."},{"id":"D","text":"Permit menținerea spațiului."},{"id":"E","text":"Sunt costisitoare și necesită etape de laborator."}],"correct":["A","B","C","D"],"pages":[394],"source":"set-2"},{"id":"set2-lH0hixh1","fingerprint":"8ee635b560db22f7","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt cauzele frecvente ale apariției cariei complicate a dinților temporari?","options":[{"id":"A","text":"Neglijarea tratamentului cariei simple și podeaua subțire a camerei pulpare."},{"id":"B","text":"Aplicarea materialelor de restaurare coronară întotdeauna cu protecție pulpară."},{"id":"C","text":"Dimensiunea mare a camerei pulpare și situarea superficială a coarnelor pulpare."},{"id":"D","text":"Folosirea intermitentă a turbinei și spălarea cavității cu substanțe neiritante."},{"id":"E","text":"Apariția tardivă a procesului carios și evoluția lentă spre profunzime."}],"correct":["A","C"],"pages":[395],"source":"set-2"},{"id":"set2-_M_UVGfA","fingerprint":"010d823fb37cb111","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care sunt formele clinice ale cariei complicate a dinților temporari?","options":[{"id":"A","text":"Caria simplă, pulpita și parodontita apicală."},{"id":"B","text":"Pulpita acută seroasă, pulpita acută purulentă și pulpita cronică."},{"id":"C","text":"Hiperemia pulpară, pulpita și sindromul de sept."},{"id":"D","text":"Pulpita, gangrena și necroza."},{"id":"E","text":"Gangrena, necroza și traumatismul dentar."}],"correct":["D"],"pages":[395],"source":"set-2"},{"id":"set2-jAR4Ntix","fingerprint":"751f341fb62b7741","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce factori favorizează cronicizarea inflamației pulpare la dinții temporari?","options":[{"id":"A","text":"Identificarea precoce a etapelor inflamației pulpare."},{"id":"B","text":"Rizaliza dintelui temporar."},{"id":"C","text":"Zona de deschidere largă în regiunea apicală."},{"id":"D","text":"Creșterea presiunii intrapulpare datorită proceselor congestive."},{"id":"E","text":"Potențialul crescut de apărare și reparație al pulpei dentare."}],"correct":["B","C"],"pages":[395],"source":"set-2"},{"id":"set2-zd9lIXah","fingerprint":"d26097e96ef152c0","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la diagnosticul pozitiv al pulpitei la dinții temporari?","options":[{"id":"A","text":"Simptomatologia dureroasă este de obicei mai accentuată decât la dinții permanenți."},{"id":"B","text":"Testele de vitalitate, precum aplicarea unui spray rece, sunt foarte concludente la copii."},{"id":"C","text":"Micii pacienți pot oferi informații detaliate și precise despre intensitatea și caracterul durerii."},{"id":"D","text":"Congestia gingivală la nivelul dintelui afectat este un semn distinctiv la inspecție."},{"id":"E","text":"O durere de tip jenă la masticație poate fi întâlnită în pulpitele cronice cu camera pulpară deschisă."}],"correct":["D","E"],"pages":[395],"source":"set-2"},{"id":"set2-scNXB2Ts","fingerprint":"fa2873ac4e0a542c","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce poate semnifica o durere acută spontană la nivelul unui dinte temporar, respectiv o durere cronică, difuză?","options":[{"id":"A","text":"Atât durerea acută, cât și cea cronică indică exclusiv o inflamație pulpară cronică."},{"id":"B","text":"Durerea acută poate indica o inflamație pulpară cronică."},{"id":"C","text":"Durerea cronică, difuză poate semnifica necroză pulpară."},{"id":"D","text":"Durerea acută spontană poate indica o inflamație pulpară acută."},{"id":"E","text":"Durerea cronică, difuză poate semnifica un sindrom de sept."}],"correct":["C","D"],"pages":[395],"source":"set-2"},{"id":"set2-tVl6afxw","fingerprint":"103d415fb4520153","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele semne obiective sunt caracteristice pulpitei acute seroase?","options":[{"id":"A","text":"La deschiderea camerei pulpare se eliberează o picătură de puroi."},{"id":"B","text":"În forma totală, este prezentă sensibilitatea la percuția în ax."},{"id":"C","text":"La deschiderea unui corn pulpar apare o picătură de sânge."},{"id":"D","text":"Pacientul relatează o ameliorare a durerii la deschiderea camerei pulpare."},{"id":"E","text":"Pulpa descoperită este insensibilă la atingere."}],"correct":["B","C"],"pages":[396],"source":"set-2"},{"id":"set2-aDOAAemi","fingerprint":"db5ee7f2d2e9ef2b","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect simptomatologia subiectivă în pulpita acută purulentă?","options":[{"id":"A","text":"Durerea este ameliorată de lichidele reci."},{"id":"B","text":"Durerea este accentuată de percuția în ax doar în fazele incipiente."},{"id":"C","text":"Durerea este frecvent declanșată sau accentuată noaptea."},{"id":"D","text":"Durerea are un caracter pulsatil."},{"id":"E","text":"Criza dureroasă este de scurtă durată și localizată."}],"correct":["A","C","D"],"pages":[396],"source":"set-2"},{"id":"set2--fBBkfHw","fingerprint":"98955d74f73079af","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Un pacient prezintă un disconfort dureros inconstant, care apare în timpul masticației. Examenul clinic relevă obturații vechi, extinse, cu semne de carie secundară. Care este cel mai probabil diagnostic?","options":[{"id":"A","text":"Pulpită acută purulentă"},{"id":"B","text":"Pulpită cronică cu camera pulpară închisă"},{"id":"C","text":"Pulpită acută seroasă"},{"id":"D","text":"Gangrenă pulpară"},{"id":"E","text":"Pulpită cronică cu camera pulpară deschisă - forma ulceroasă"}],"correct":["B"],"pages":[396],"source":"set-2"},{"id":"set2-J_y4lYso","fingerprint":"0665fd210dd642ad","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În pulpita cronică cu camera pulpară deschisă, forma ulceroasă, care este mecanismul principal al apariției sensibilității la masticație?","options":[{"id":"A","text":"Inflamația acută a ligamentelor parodontale."},{"id":"B","text":"Prezența unei carii secundare sub o obturație veche."},{"id":"C","text":"Contactul alimentelor reci cu pulpa expusă."},{"id":"D","text":"Presiunea exercitată de alimente asupra țesutului de granulație."},{"id":"E","text":"Eliberarea de puroi sub presiune ocluzală."}],"correct":["D"],"pages":[396],"source":"set-2"},{"id":"set2-cCjAtjeN","fingerprint":"6e971b8a1d040410","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afecțiuni pulpare se caracterizează prin prezența sensibilității la percuția în ax în forma sa totală?","options":[{"id":"A","text":"Pulpita cronică cu camera pulpară închisă"},{"id":"B","text":"Pulpita acută seroasă totală"},{"id":"C","text":"Pulpita cronică cu camera pulpară deschisă"},{"id":"D","text":"Pulpita acută seroasă parțială"},{"id":"E","text":"Pulpita acută purulentă totală"}],"correct":["B","E"],"pages":[396],"source":"set-2"},{"id":"set2-vAk7vSKP","fingerprint":"fa2bd7978898c27a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce descrie evoluția inițială a unei pulpite acute seroase?","options":[{"id":"A","text":"Debutează întotdeauna cu o durere intensă, pulsatilă și continuă."},{"id":"B","text":"Este prima etapă în evoluția unei afecțiuni pulpare și poate trece neobservată."},{"id":"C","text":"Este o afecțiune pulpară complet asimptomatică."},{"id":"D","text":"Simptomatologia este ameliorată de aplicarea de lichide reci."},{"id":"E","text":"Se manifestă obiectiv prin prezența unei camere pulpare deschise cu țesut de granulație."}],"correct":["B"],"pages":[396],"source":"set-2"},{"id":"set2-cMnmo8CP","fingerprint":"ab0314cb9273759b","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt caracteristicile polipului pulpar în pulpita cronică cu camera pulpară deschisă, forma granulomatoasă?","options":[{"id":"A","text":"Este ferm atașat de pereții cavității carioase."},{"id":"B","text":"Sângerează la atingere și este detașabil."},{"id":"C","text":"Este format din țesut de granulație lax, bine vascularizat și de culoare roșie."},{"id":"D","text":"Este insensibil la palpare în zonele sale superficiale."},{"id":"E","text":"Prezintă terminații nervoase abundente pe toată suprafața sa."}],"correct":["B","C","D"],"pages":[397],"source":"set-2"},{"id":"set2-lGSW7sRs","fingerprint":"28b864f3ad423a8d","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care este elementul cheie pentru a stabili diagnosticul diferențial între un polip pulpar și un polip gingival?","options":[{"id":"A","text":"Analiza dimensiunii cavității carioase."},{"id":"B","text":"Observarea răspunsului la sângerare după atingere."},{"id":"C","text":"Testarea sensibilității la palparea cu sonda."},{"id":"D","text":"Evaluarea culorii formațiunii tisulare."},{"id":"E","text":"Identificarea bazei de implantare a polipului."}],"correct":["E"],"pages":[397],"source":"set-2"},{"id":"set2-z-hV5H1p","fingerprint":"9b1dce074e1d92f4","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce simptome subiective sunt asociate cu pulpita cronică granulomatoasă (polipoasă)?","options":[{"id":"A","text":"Sensibilitate accentuată la stimuli termici reci."},{"id":"B","text":"Absența completă a oricărui disconfort sau durere."},{"id":"C","text":"Sângerare localizată dacă polipul a fost lezat."},{"id":"D","text":"Disconfort la masticație."},{"id":"E","text":"Durere spontană, intensă și iradiată."}],"correct":["C","D"],"pages":[397],"source":"set-2"},{"id":"set2-EW21LUsq","fingerprint":"58285f70fd1196c7","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afecțiuni sunt incluse în diagnosticul diferențial al pulpitelor?","options":[{"id":"A","text":"Sinuzita maxilară."},{"id":"B","text":"Otita."},{"id":"C","text":"Nevralgia de trigemen."},{"id":"D","text":"Parodontita apicală acută."},{"id":"E","text":"Amigdalita."}],"correct":["B","D","E"],"pages":[397],"source":"set-2"},{"id":"set2-d8EWcr-8","fingerprint":"11190d5cbc6e73f1","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre enunțurile de mai jos reprezintă obiective ale tratamentului pulpitelor la dinții temporari?","options":[{"id":"A","text":"Combaterea durerii și tratamentul leziunii pulpare."},{"id":"B","text":"Accelerarea procesului de rizaliză pentru a facilita erupția dintelui permanent."},{"id":"C","text":"Refacerea morfo-funcțională a dintelui temporar în acord cu stadiul său evolutiv."},{"id":"D","text":"Extracția sistematică a dintelui afectat pentru a preveni infecția dintelui permanent."},{"id":"E","text":"Menținerea dintelui temporar pe arcadă până la înlocuirea sa fiziologică."}],"correct":["A","C","E"],"pages":[397],"source":"set-2"},{"id":"set2-K88y1VvN","fingerprint":"eb2ca96f0a688644","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce factori specifici complică diagnosticul și tratamentul pulpitelor la dinții temporari?","options":[{"id":"A","text":"Capacitatea de apărare a pulpei, care este constant ridicată indiferent de stadiul de dezvoltare."},{"id":"B","text":"Dependența testelor clinice de vitalitate de colaborarea cu pacientul copil."},{"id":"C","text":"Structura simplificată și constantă a canalelor radiculare la dinții temporari."},{"id":"D","text":"Dificultatea în obținerea unor radiografii clare, fără superpoziții."},{"id":"E","text":"Complexitatea și variabilitatea sistemului endodontic."}],"correct":["B","D","E"],"pages":[397],"source":"set-2"},{"id":"set2-K0nEDEdc","fingerprint":"7c1f3090823c4d52","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele aspecte reprezintă dificultăți în diagnosticul și tratamentul pulpitelor la dinții temporari?","options":[{"id":"A","text":"Prezența canalelor radiculare accesorii, care simplifică tratamentul endodontic."},{"id":"B","text":"Înălțimea redusă a camerei pulpare, crescând riscul de perforații."},{"id":"C","text":"Precizia ridicată a radiografiilor panoramice, care elimină suprapunerile."},{"id":"D","text":"Testele clinice de vitalitate care sunt independente de colaborarea pacientului."},{"id":"E","text":"Comunicarea pulpo-parodontală."}],"correct":["B","E"],"pages":[398],"source":"set-2"},{"id":"set2-dfSfh2W3","fingerprint":"1efcc2ec72a02903","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În ce situație clinică este indicată extirparea (pulpectomia) vitală la un dinte temporar?","options":[{"id":"A","text":"La pacienți non-complianți unde nu se pot respecta exigențele de izolare."},{"id":"B","text":"În cazul pulpitelor totale la dinții cu rădăcina formată."},{"id":"C","text":"Dacă timpul până la exfolierea fiziologică este mai mic de un an."},{"id":"D","text":"În cazul cariilor profunde la dinții temporari cu rădăcinile în formare."},{"id":"E","text":"În deschiderile accidentale ale camerei pulpare de dimensiuni mari."}],"correct":["B"],"pages":[398],"source":"set-2"},{"id":"set2-anNZjTQb","fingerprint":"bf4153724dc54048","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele reprezintă indicații pentru un tratament endodontic conservativ al unui dinte temporar cu afecțiune pulpară?","options":[{"id":"A","text":"Menținerea spațiului pentru prevenirea migrărilor post-extracționale."},{"id":"B","text":"Agenezia dintelui succesional."},{"id":"C","text":"Resorbții radiculare patologice avansate."},{"id":"D","text":"Distrucție coronară masivă, astfel încât dintele nu își mai păstrează funcțiile."},{"id":"E","text":"Risc medical cardiac sau imunologic."}],"correct":["A","B"],"pages":[398],"source":"set-2"},{"id":"set2-9MO9evQL","fingerprint":"e878f63f3ceafc0e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce tehnică de tratament este recomandată pentru un pacient non-compliant cu pulpită la un dinte temporar tânăr, cu rădăcini complet formate?","options":[{"id":"A","text":"Pulpectomie devitală."},{"id":"B","text":"Amputație (pulpotomie) vitală."},{"id":"C","text":"Extracție dentară."},{"id":"D","text":"Coafaj indirect."},{"id":"E","text":"Extirpare (pulpectomie) vitală."}],"correct":["A"],"pages":[398],"source":"set-2"},{"id":"set2-lFQG3cUP","fingerprint":"31cde8c8a4c1692d","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"În care dintre următoarele situații este indicată extracția unui dinte temporar cu afecțiune pulpară?","options":[{"id":"A","text":"Indicații medicale precum hemofilia sau diabetul."},{"id":"B","text":"Prezența unei carii penetrante în planșeul camerei pulpare."},{"id":"C","text":"Existența unei carii profunde cu pierderea peretelui proximal."},{"id":"D","text":"Dentație mixtă cu înghesuiri."},{"id":"E","text":"Resorbție radiculară care afectează mai mult de 2/3 din rădăcină."}],"correct":["B","D","E"],"pages":[398],"source":"set-2"},{"id":"set2-48JX3aHN","fingerprint":"471b888242276ebd","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce diferențiază, conform indicațiilor, coafajul direct de amputația (pulpotomia) vitală în tratamentul dinților temporari?","options":[{"id":"A","text":"Coafajul direct se aplică la dinți cu rădăcina formată, iar pulpotomia vitală la dinți cu rădăcina în formare."},{"id":"B","text":"Coafajul direct este pentru deschideri accidentale ale camerei pulpare, iar pulpotomia vitală este pentru carii profunde."},{"id":"C","text":"Pulpotomia vitală se realizează în deschideri accidentale mai mari, în timp ce coafajul direct este pentru cele de dimensiuni mai mici."},{"id":"D","text":"Coafajul direct este o tehnică devitală, spre deosebire de pulpotomia vitală."},{"id":"E","text":"Coafajul direct este pentru pacienți non-complianți, iar pulpotomia vitală pentru pacienți complianți."}],"correct":["C"],"pages":[398],"source":"set-2"},{"id":"set2-lOwiYcgA","fingerprint":"c332ffa4d2e27900","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afecțiuni reprezintă indicații pentru coafajul indirect la dinții temporari aflați în stadiul 1 sau 2?","options":[{"id":"A","text":"Hiperemie pulpară."},{"id":"B","text":"Deschidere accidentală de dimensiune redusă a camerei pulpare."},{"id":"C","text":"Traumatisme dentare fără deschiderea camerei pulpare."},{"id":"D","text":"Pulpită seroasă parțială."},{"id":"E","text":"Pacient necooperant."}],"correct":["A","C","D"],"pages":[399],"source":"set-2"},{"id":"set2-BBzFclUu","fingerprint":"9ef5d4d7e62b3dc6","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la tehnica de coafaj indirect?","options":[{"id":"A","text":"Controlul postoperator imediat se realizează la 3-6 luni."},{"id":"B","text":"Se aplică un material bio-activ, precum hidroxidul de calciu sau eugenatul de zinc, pentru a stimula depunerea de dentină terțiară."},{"id":"C","text":"Obturația coronară definitivă se realizează imediat după aplicarea materialului de coafaj, indiferent de stadiul dintelui."},{"id":"D","text":"Succesul metodei este confirmat radiologic prin apariția unui strat calcificat sub materialul de coafaj."},{"id":"E","text":"Scopul exerezei dentinei alterate este de a deschide camera pulpară pentru a asigura drenajul."}],"correct":["B","D"],"pages":[399],"source":"set-2"},{"id":"set2-n-6H_aEO","fingerprint":"7bf65eaa85a73530","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care este dezideratul principal al coafajului direct și în ce condiție fundamentală nu poate fi acesta atins?","options":[{"id":"A","text":"Păstrarea vitalității pulpare, obiectiv ce nu poate fi îndeplinit dacă pulpa dentară este inflamată și infectată."},{"id":"B","text":"Menținerea vitalității pulpare prin plasarea unui biomaterial pe pereții laterali ai cavității."},{"id":"C","text":"Crearea unei soluții de continuitate la nivelul plafonului camerei pulpare pentru a elibera presiunea."},{"id":"D","text":"Stimularea depunerii de dentină terțiară, proces care are loc chiar și în prezența contaminării cu salivă."},{"id":"E","text":"Asigurarea funcționalității dintelui, indiferent de starea de sănătate a pulpei dentare."}],"correct":["A"],"pages":[399],"source":"set-2"},{"id":"set2-w5niiexS","fingerprint":"125662a7b4c98b25","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În care dintre următoarele situații este indicat coafajul direct?","options":[{"id":"A","text":"Pulpită seroasă parțială."},{"id":"B","text":"Deschidere accidentală de dimensiune redusă a camerei pulpare, în lipsa contaminării cu salivă."},{"id":"C","text":"Pacient cu complianță scăzută pentru controale periodice."},{"id":"D","text":"Hiperemie pulpară cu camera pulpară închisă."},{"id":"E","text":"Traumatisme dentare care nu au produs deschiderea camerei pulpare."}],"correct":["B"],"pages":[399],"source":"set-2"},{"id":"set2-xkUfpM4k","fingerprint":"9e055a9a3efb272f","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce factori contribuie la un prognostic bun în cazul tratamentului prin coafaj indirect?","options":[{"id":"A","text":"O capacitate bună de apărare a pulpei dentare."},{"id":"B","text":"O cantitate redusă de dentină infectată."},{"id":"C","text":"Aplicarea tratamentului la timpul potrivit."},{"id":"D","text":"Realizarea restaurării coronare definitive înainte de controlul postoperator."},{"id":"E","text":"Îndepărtarea unei cantități cât mai reduse de dentină alterată."}],"correct":["A","B","C"],"pages":[399],"source":"set-2"},{"id":"set2-2qaC616D","fingerprint":"85a63dc862680b4b","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce materiale cu proprietăți bio-active, care stimulează capacitatea reparatorie a pulpei dentare, sunt menționate pentru utilizare în tehnicile de coafaj?","options":[{"id":"A","text":"Eugenat de zinc."},{"id":"B","text":"MTA (Mineral Trioxide Aggregate)."},{"id":"C","text":"Hidroxid de calciu."},{"id":"D","text":"Ser fiziologic."},{"id":"E","text":"Clorhexidină."}],"correct":["A","B","C"],"pages":[399],"source":"set-2"},{"id":"set2-pmXkhuyu","fingerprint":"08578d53777be356","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În care dintre următoarele situații clinice este indicat coafajul direct la dinții temporari?","options":[{"id":"A","text":"Existența unor leziuni inter-radiculare."},{"id":"B","text":"Pulpită seroasă parțială."},{"id":"C","text":"Deschideri accidentale ale camerei pulpare sau inflamație pulpară de dată recentă, limitată la pulpa coronară."},{"id":"D","text":"Carie profundă simptomatică."},{"id":"E","text":"Dinte temporar în stadiul 3 evolutiv."}],"correct":["C"],"pages":[400],"source":"set-2"},{"id":"set2-2JaOPNWG","fingerprint":"95f3f06ecdb0bcb2","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele reprezintă indicații pentru realizarea unei pulpotomii vitale la dinții temporari?","options":[{"id":"A","text":"Traumatism dentar cu deschiderea camerei pulpare la un dinte în stadiul 1 sau 2."},{"id":"B","text":"Hiperemie pulpară."},{"id":"C","text":"Pulpită acută seroasă parțială."},{"id":"D","text":"Dinte temporar în stadiul 3 evolutiv."},{"id":"E","text":"Copii cu patologie generală asociată."}],"correct":["A","B","C"],"pages":[400],"source":"set-2"},{"id":"set2-dkNKZrur","fingerprint":"a092ff809f148e4e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt contraindicațiile pulpotomiei vitale la dinții temporari?","options":[{"id":"A","text":"Hiperemie pulpară."},{"id":"B","text":"Dinte temporar cu carie profundă, simptomatică."},{"id":"C","text":"Rezorbție radiculară inflamatorie."},{"id":"D","text":"Existența unor leziuni apicale sau inter-radiculare."},{"id":"E","text":"Dinte temporar în stadiul 3 evolutiv."}],"correct":["C","D","E"],"pages":[400],"source":"set-2"},{"id":"set2-0lQq4FLW","fingerprint":"ea5251a47df1b84c","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce elemente fac parte din secvența tehnică a pulpotomiei vitale?","options":[{"id":"A","text":"Îndepărtarea pulpei coronare exclusiv cu lingurițe Black active."},{"id":"B","text":"Refacerea morfologiei coronare cu un material de obturație, cum ar fi un ciment ionomer de sticlă."},{"id":"C","text":"Aplicarea unui material bioactiv precum ZOE cu priză rapidă, hidroxid de calciu sau MTA la nivelul camerei pulpare."},{"id":"D","text":"Realizarea hemostazei cu o buletă de vată sterilă cu ser fiziologic, aplicată compresiv."},{"id":"E","text":"Efectuarea unei radiografii de control la 1-2 săptămâni postoperator."}],"correct":["B","C","D"],"pages":[400],"source":"set-2"},{"id":"set2-4-7kl9Yq","fingerprint":"1b70032bad9585b0","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care este protocolul de monitorizare și evaluare a succesului în cazul unei pulpotomii vitale la un dinte temporar?","options":[{"id":"A","text":"Se realizează un control radiologic la 3 luni pentru a aprecia succesul sau insuccesul metodei."},{"id":"B","text":"Se efectuează controale regulate la 3-6 luni până la exfolierea dintelui."},{"id":"C","text":"Control clinic la 1-2 săptămâni, urmat de controale periodice la 3-6 luni."},{"id":"D","text":"Prognosticul este considerat favorabil dacă se realizează corect din punct de vedere tehnic și diagnostic."},{"id":"E","text":"Succesul este evidențiat radiologic prin apariția unui strat calcificat dedesubtul materialului aplicat."}],"correct":["A","B","D"],"pages":[400],"source":"set-2"},{"id":"set2-Vni8oZIu","fingerprint":"4e4f1cd1ea941845","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații reprezintă indicații pentru efectuarea unei pulpectomii vitale la dinții temporari?","options":[{"id":"A","text":"Pacientul este un copil cu patologie generală asociată."},{"id":"B","text":"Existența unor resorbții radiculare patologice."},{"id":"C","text":"Dintele temporar se află în stadiul 3 evolutiv."},{"id":"D","text":"Evoluția nefavorabilă a unei pulpotomii efectuate anterior."},{"id":"E","text":"Prezența unor pulpite totale la dinți temporari aflați în stadiul 2 evolutiv."}],"correct":["D","E"],"pages":[401],"source":"set-2"},{"id":"set2-_OlSUgNr","fingerprint":"972388bc6688b195","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce aspecte sunt esențiale în timpul etapei de preparare a canalelor radiculare în cadrul unei pulpectomii vitale la un dinte temporar?","options":[{"id":"A","text":"Canalele radiculare trebuie preparate cel puțin cu un ac Kerr 25 cu conicitate 2% până la nivelul apexului."},{"id":"B","text":"Îndepărtarea pulpei radiculare se realizează cu freze globulare."},{"id":"C","text":"Stabilirea lungimii de lucru se face astfel încât să nu fie afectat mugurele dintelui permanent."},{"id":"D","text":"Uscarea canalului se face exclusiv cu jet de aer."},{"id":"E","text":"Irigarea se face permanent cu hipoclorit de sodiu în concentrație de 2,5-5%."}],"correct":["A","C","E"],"pages":[401],"source":"set-2"},{"id":"set2-yEVy8xgs","fingerprint":"9542211225193be4","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce materiale pot fi utilizate pentru obturarea canalelor radiculare după finalizarea preparării acestora în cadrul pulpectomiei vitale?","options":[{"id":"A","text":"MTA (Mineral Trioxide Aggregate)."},{"id":"B","text":"Pastă de ZOE de consistență cremoasă."},{"id":"C","text":"Hidroxid de calciu."},{"id":"D","text":"Un preparat pe bază de paraformaldehidă."},{"id":"E","text":"Un ciment ionomer de sticlă (CIS) de consistență crescută."}],"correct":["A","B","C"],"pages":[401],"source":"set-2"},{"id":"set2-Y5FH5Nxp","fingerprint":"91f8ec7c47839955","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care este protocolul de monitorizare radiologică după realizarea unei pulpectomii vitale la un dinte temporar?","options":[{"id":"A","text":"Un control radiologic la 3 luni pentru a aprecia succesul sau insuccesul metodei."},{"id":"B","text":"O singură radiografie de control la 6 luni, considerată suficientă."},{"id":"C","text":"Controale regulate la 3-6 luni până la exfolierea dintelui."},{"id":"D","text":"O radiografie retroalveolară de control imediat după restaurarea coronară."},{"id":"E","text":"Controale regulate la 1-2 luni până la exfolierea dintelui."}],"correct":["A","C"],"pages":[401],"source":"set-2"},{"id":"set2-2crFxnk9","fingerprint":"4d7fdf949601681a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"În ce situații este indicată pulpotomia devitală, pe lângă indicațiile comune cu pulpotomia vitală?","options":[{"id":"A","text":"Pacientul este foarte cooperant."},{"id":"B","text":"Există o resorbție radiculară accentuată."},{"id":"C","text":"Există contraindicații relative ale anesteziei locale."},{"id":"D","text":"Izolarea câmpului operator este imposibilă."},{"id":"E","text":"Pacientul este non-compliant."}],"correct":["C","D","E"],"pages":[401],"source":"set-2"},{"id":"set2-0Vz1LseI","fingerprint":"508efd46b344d28c","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce element distinctiv caracterizează tehnica pulpotomiei devitale în prima ședință?","options":[{"id":"A","text":"Se realizează obturația de canal cu MTA."},{"id":"B","text":"Se aplică un preparat medicamentos cu paraformaldehidă la nivelul deschiderii camerei pulpare."},{"id":"C","text":"Se îndepărtează complet pulpa coronară și radiculară."},{"id":"D","text":"Se realizează restaurarea coronară finală cu o coroană pedodontică preformată."},{"id":"E","text":"Se irigă abundent camera pulpară cu hipoclorit de sodiu."}],"correct":["B"],"pages":[401],"source":"set-2"},{"id":"set2-DB2ZMue-","fingerprint":"f7110af89d931c87","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt indicațiile pentru pulpectomia devitală la dinții temporari?","options":[{"id":"A","text":"Pacient non-compliant."},{"id":"B","text":"Dinți temporari cu rădăcina neresorbită sau cu resorbție mai mică de două treimi."},{"id":"C","text":"Resorbție radiculară importantă."},{"id":"D","text":"Prezența unor afecțiuni generale."},{"id":"E","text":"Pacient cooperant."}],"correct":["A","B","D"],"pages":[402],"source":"set-2"},{"id":"set2-LX80K8qn","fingerprint":"cb8620f0db8b1343","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce compoziție are preparatul medicamentos utilizat în prima ședință a pulpectomiei devitale pentru a desensibiliza țesutul pulpar?","options":[{"id":"A","text":"Eugenol și oxid de zinc."},{"id":"B","text":"Un antibiotic cu spectru larg și un antiinflamator."},{"id":"C","text":"Paraformaldehidă și un anestezic."},{"id":"D","text":"Corticosteroizi și agenți antifungici."},{"id":"E","text":"Hidroxid de calciu și sulfat de bariu."}],"correct":["C"],"pages":[402],"source":"set-2"},{"id":"set2-LRdNmgJz","fingerprint":"d4a368111d4529f8","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care este diferența fundamentală dintre necroza pulpară și gangrena pulpară?","options":[{"id":"A","text":"Flora microbiană din necroză este exclusiv aerobă, iar în gangrenă este exclusiv anaerobă."},{"id":"B","text":"Gangrena nu implică alterarea pereților dentinari, spre deosebire de necroză."},{"id":"C","text":"Gangrena implică procese de fermentație și putrefacție, în timp ce necroza nu."},{"id":"D","text":"Necroza afectează doar dinții temporari, iar gangrena doar pe cei permanenți."},{"id":"E","text":"Necroza este un proces septic, în timp ce gangrena este aseptică."}],"correct":["C"],"pages":[402],"source":"set-2"},{"id":"set2-OXEmThzQ","fingerprint":"9c43a1d6d01f7718","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele reprezintă cauze ale gangrenei pulpare la dinții temporari?","options":[{"id":"A","text":"Invazia microbiană directă pe o pulpă sănătoasă după un traumatism cu expunere largă."},{"id":"B","text":"Utilizarea unei cantități excesive de produs devitalizant în pulpectomie."},{"id":"C","text":"Rizaliza fiziologică a dintelui."},{"id":"D","text":"Necroze pulpare infectate printr-o soluție de continuitate."},{"id":"E","text":"Caria profundă cu deschiderea camerei pulpare."}],"correct":["A","D","E"],"pages":[402],"source":"set-2"},{"id":"set2-MrEH80jm","fingerprint":"f130237435956384","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce caracteristici definesc gangrena pulpară complicată?","options":[{"id":"A","text":"Flora microbiană implicată este exclusiv aerobă."},{"id":"B","text":"Rizaliza dinților temporari acționează ca o barieră, prevenind extinderea infecției."},{"id":"C","text":"Procesul infecțios se extinde și cuprinde țesuturile periapicale și parodontale."},{"id":"D","text":"Este o mortificare aseptică a țesuturilor pulpare și periapicale."},{"id":"E","text":"Procesul infecțios este limitat strict la țesuturile pulpare."}],"correct":["C"],"pages":[402],"source":"set-2"},{"id":"set2-9afpvvuh","fingerprint":"c0ddcb914caa166b","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce factori sunt luați în considerare la alegerea metodei de tratament pentru gangrena unui dinte temporar?","options":[{"id":"A","text":"Importanța dintelui în menținerea spațiului pentru dinții permanenți."},{"id":"B","text":"Vârsta dentară și cea cronologică a pacientului."},{"id":"C","text":"Gradul de distrucție coronară."},{"id":"D","text":"Gradul de interesare a osului alveolar."},{"id":"E","text":"Tipul specific de anestezic utilizat în tratamentele anterioare."}],"correct":["A","B","C","D"],"pages":[402],"source":"set-2"},{"id":"set2-fGccvglw","fingerprint":"efcfd57c27db35e9","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următorii factori sunt luați în considerare în alegerea metodei de tratament pentru un dinte temporar afectat de gangrenă?","options":[{"id":"A","text":"Complianța și colaborarea cu pacientul și familia sa."},{"id":"B","text":"Costul estimat al procedurilor de restaurare coronară."},{"id":"C","text":"Gradul de distrucție coronară și de rezorbție radiculară."},{"id":"D","text":"Importanța dintelui pentru menținerea spațiului, în corelație cu vârsta dentară și cronologică."},{"id":"E","text":"Gradul de interesare a osului alveolar."}],"correct":["A","C","D","E"],"pages":[403],"source":"set-2"},{"id":"set2-gMfzkELk","fingerprint":"2b5ed2e61731b727","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce etape include tratamentul mecanic în abordarea conservativă a unui dinte temporar?","options":[{"id":"A","text":"Împingerea deliberată a detritusurilor infectate dincolo de apex pentru a stimula un răspuns imun local."},{"id":"B","text":"Utilizarea conurilor de guttapercha pentru o sigilare optimă a canalelor radiculare."},{"id":"C","text":"Izolarea dintelui cu sistem de digă."},{"id":"D","text":"Permeabilizarea canalelor cu instrumente endodontice și verificarea constantă a lungimii radiculare."},{"id":"E","text":"Îndepărtarea procesului carios și a detritusurilor de la nivelul camerei pulpare."}],"correct":["C","D","E"],"pages":[403],"source":"set-2"},{"id":"set2-_EpXnlAm","fingerprint":"5105bf859cacafe9","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Referitor la tratamentul chimic al sistemului endodontic, care afirmație despre hipocloritul de sodiu este corectă?","options":[{"id":"A","text":"Are capacitatea de a neutraliza selectiv doar agenții patogeni anaerobi din sistemul endodontic."},{"id":"B","text":"Utilizarea sa este recomandată în special la copiii necooperanți deoarece nu necesită măsuri de izolare."},{"id":"C","text":"Principalul său avantaj este că poate fi folosit fără sistem de digă."},{"id":"D","text":"Este considerat agentul dezinfectant de elecție în afecțiunile pulpare avansate."},{"id":"E","text":"Acționează sinergic cu clorhexidina, fiind obligatorie utilizarea lor combinată."}],"correct":["D"],"pages":[403],"source":"set-2"},{"id":"set2-5TVM0qCe","fingerprint":"db8002bd5dffd044","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele situații clinice reprezintă indicații pentru extracția unui dinte temporar?","options":[{"id":"A","text":"Dintele nu are importanță funcțională."},{"id":"B","text":"Prezența unor complicații grave, precum abcesele repetate."},{"id":"C","text":"Existența unei distrucții coronare foarte mari la un copil colaborant."},{"id":"D","text":"Apariția unor acutizări repetate care periclitează dezvoltarea germenilor dinților permanenți."},{"id":"E","text":"Morfologie complexă a canalelor radiculare ce împiedică tratamentul conservator."}],"correct":["A","B","D"],"pages":[403],"source":"set-2"},{"id":"set2-ArRTOLc_","fingerprint":"d8707899c55f185a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În ce situație este indicată o măsură de compromis, precum evidarea camerei pulpare și lăsarea dintelui deschis?","options":[{"id":"A","text":"La un copil cu o stare de sănătate dentară și generală excelentă și colaborare perfectă."},{"id":"B","text":"Atunci când extracția are o indicație categorică."},{"id":"C","text":"În cazul succesului unui tratament conservator anterior."},{"id":"D","text":"În cazul unor condiții ocluzale nefavorabile aplicării menținătorului de spațiu, înaintea erupției molarului de 6 ani."},{"id":"E","text":"La pacienți cu patologie generală ce presupune eliminarea focarelor dentare."}],"correct":["D"],"pages":[403],"source":"set-2"},{"id":"set2-RnuafEH8","fingerprint":"c61b5d9f75e4b550","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce caracterizează parodontita apicală acută ca o complicație a gangrenei la dinții temporari?","options":[{"id":"A","text":"Este un proces inflamator localizat, ce evoluează lent, exclusiv în faza endoosoasă."},{"id":"B","text":"Exteriorizarea procesului la incisivii temporari are loc în zona furcației."},{"id":"C","text":"Evoluția sa se oprește întotdeauna în faza subperiostală."},{"id":"D","text":"Prezintă trei faze de evoluție: endoosoasă, subperiostală și submucoasă."},{"id":"E","text":"La molarii temporari, procesul se exteriorizează de obicei strict în zona apicală."}],"correct":["D"],"pages":[403],"source":"set-2"},{"id":"set2-ozG0zxYr","fingerprint":"836af0310f9ac4ca","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care este protocolul standard de monitorizare după finalizarea unui tratament conservativ la un dinte temporar?","options":[{"id":"A","text":"Monitorizarea nu este necesară, succesul fiind evaluat exclusiv pe baza simptomatologiei pacientului."},{"id":"B","text":"Un singur control radiologic la 12 luni post-tratament."},{"id":"C","text":"Un control radiologic la 3 luni, urmat de controale regulate la 3-6 luni până la exfoliere."},{"id":"D","text":"Controale clinice anuale, fără a fi necesare investigații radiologice."},{"id":"E","text":"Controale lunare până la exfolierea dintelui, atât clinice, cât și radiologice."}],"correct":["C"],"pages":[403],"source":"set-2"},{"id":"set2-XiuSret3","fingerprint":"c001bde37d118fd8","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele semne și simptome subiective sunt caracteristice parodontitei apicale acute la copii?","options":[{"id":"A","text":"Dureri difuze, șterse, adesea ignorate de pacient."},{"id":"B","text":"Durere spontană, de intensitate mare, greu de localizat de către copil."},{"id":"C","text":"Sensibilitate crescută la stimuli termici reci."},{"id":"D","text":"Absența totală a durerii, leziunea fiind asimptomatică."},{"id":"E","text":"Sensibilitate la masticație la nivelul dintelui afectat."}],"correct":["B","E"],"pages":[404],"source":"set-2"},{"id":"set2-oc-DP5QT","fingerprint":"c6d3e32e14050c5c","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce semne obiective pot fi identificate în cadrul examenului clinic al unui dinte temporar cu parodontită apicală acută?","options":[{"id":"A","text":"Mobilitate dentară gradul III în toate cazurile."},{"id":"B","text":"Sensibilitate la percuția în ax."},{"id":"C","text":"Abces parulic sau congestie și tumefacție gingivală."},{"id":"D","text":"Proces carios superficial, fără afectarea camerei pulpare."},{"id":"E","text":"Sensibilitate la sondarea camerei pulpare."}],"correct":["B","C"],"pages":[404],"source":"set-2"},{"id":"set2-Tj_LuCNH","fingerprint":"066c8c190a45951d","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care dintre următoarele afecțiuni este inclusă în diagnosticul diferențial al parodontitei apicale acute?","options":[{"id":"A","text":"Nevralgia de trigemen."},{"id":"B","text":"Sinuzita maxilară."},{"id":"C","text":"Pulpita acută seroasă totală."},{"id":"D","text":"Otita."},{"id":"E","text":"Gingivostomatita herpetică."}],"correct":["D"],"pages":[404],"source":"set-2"},{"id":"set2-_28Epsre","fingerprint":"4a7169c67125bebf","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce obiective și proceduri include tratamentul de urgență al parodontitei apicale acute?","options":[{"id":"A","text":"Suprimarea focarului infecțios și a procesului inflamator."},{"id":"B","text":"Extracția dintelui ca primă intenție în toate situațiile."},{"id":"C","text":"Incizia la nivelul colecției purulente, dacă există un abces."},{"id":"D","text":"Realizarea drenajului endodontic prin deschiderea camerei pulpare și evidarea canalelor."},{"id":"E","text":"Obturarea de canal imediată după deschiderea camerei pulpare."}],"correct":["A","C","D"],"pages":[404],"source":"set-2"},{"id":"set2-zKfgUhXf","fingerprint":"e0291d9cd8386042","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce informații relevante poate oferi examenul radiologic în parodontita apicală acută la dinții temporari?","options":[{"id":"A","text":"Imagine de radiotransparență bine delimitată, specifică unui chist."},{"id":"B","text":"Îngroșarea spațiului periodontal, fără alte modificări osoase."},{"id":"C","text":"Stadiul evolutiv al dintelui temporar."},{"id":"D","text":"Gradul de rizaliză, care influențează decizia de a conserva sau extrage dintele."},{"id":"E","text":"Prezența unei resorbții interradiculare și/sau apicale extinse."}],"correct":["C","D","E"],"pages":[404],"source":"set-2"},{"id":"set2-A5TeTAjS","fingerprint":"fc9783a67b784a7e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce definește parodontita apicală cronică difuză?","options":[{"id":"A","text":"Poate debuta exclusiv prin cronicizarea unei forme acute."},{"id":"B","text":"O afecțiune caracterizată prin rezorbția structurilor osoase și înlocuirea lor cu țesut de granulație."},{"id":"C","text":"O afecțiune ce se vindecă spontan fără tratament."},{"id":"D","text":"O reacție de condensare osoasă periapicală ca răspuns la o infecție de slabă intensitate."},{"id":"E","text":"O inflamație acută a parodonțiului apical, întotdeauna simptomatică."}],"correct":["B"],"pages":[404],"source":"set-2"},{"id":"set2-_XXyX9QI","fingerprint":"970281c2ed058510","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele constatări clinice și radiologice sunt specifice parodontitei apicale cronice difuze?","options":[{"id":"A","text":"Prezența unei fistule sau a unei zone congestive de 4-5 mm în dreptul apexului."},{"id":"B","text":"Imagine radiologică de radiopacitate difuză periapicală."},{"id":"C","text":"Sensibilitate la percuția în ax și tumefacție pronunțată."},{"id":"D","text":"Imagine radiologică de radiotransparență interradiculară."},{"id":"E","text":"Evoluție clinică asimptomatică sau cu dureri difuze, șterse."}],"correct":["A","D","E"],"pages":[404],"source":"set-2"},{"id":"set2-OPN0aOos","fingerprint":"e4b9b5c98ff5ea94","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce factori influențează decizia terapeutică în cazul parodontitei apicale cronice la un dinte temporar?","options":[{"id":"A","text":"Extracția este indicată dacă dintele are episoade frecvente de reacutizare."},{"id":"B","text":"Dacă rămâne asimptomatică, tratamentul se corelează cu stadiul evolutiv al dintelui."},{"id":"C","text":"Se optează pentru extracție imediat ce mugurele dintelui permanent este vizibil radiologic."},{"id":"D","text":"Tratamentul endodontic este contraindicat la dinții temporari cu această afecțiune."},{"id":"E","text":"În caz de acutizare, tratamentul este identic cu cel al parodontitei apicale acute."}],"correct":["A","B","E"],"pages":[404],"source":"set-2"},{"id":"set2-79Bj_BbL","fingerprint":"d1e3f2dcdf7285ad","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect stadiul de dinte temporar tânăr?","options":[{"id":"A","text":"Pulpa dentară prezintă depuneri calcare și un potențial defensiv scăzut."},{"id":"B","text":"Procesul de dezvoltare a dintelui începe în luna a doua a vieții intrauterine."},{"id":"C","text":"Formarea rădăcinii continuă pentru o perioadă de încă 1-2 ani posteruptiv."},{"id":"D","text":"Erupția dinților temporari în cavitatea bucală are loc între 6 și 30 de luni."},{"id":"E","text":"Edificarea rădăcinii se finalizează strict în momentul erupției dentare."}],"correct":["B","C","D"],"pages":[388],"source":"set-2"},{"id":"set2-3379-q_z","fingerprint":"cde62cb47704ca29","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Referitor la particularitățile dintelui temporar matur, care dintre următoarele elemente morfologice sunt caracteristice?","options":[{"id":"A","text":"Coarnele pulpare sunt situate profund în masa dentinară."},{"id":"B","text":"Canalele radiculare au un calibru mărit."},{"id":"C","text":"Canaliculele dentinare au un calibru larg."},{"id":"D","text":"Rădăcinile sunt gracile și divergente, cuprinzând mugurii dinților permanenți de înlocuire."},{"id":"E","text":"Camera pulpară are dimensiuni mari comparativ cu grosimea țesuturilor dure dentare."}],"correct":["C","D","E"],"pages":[388],"source":"set-2"},{"id":"set2-i1s-yL7l","fingerprint":"b3a238a62f4d954c","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Din punct de vedere cronologic și structural, care dintre următoarele afirmații descriu stadiul dintelui temporar cu rădăcina în resorbție?","options":[{"id":"A","text":"Debutul rizalizei la molarii temporari începe la vârsta de 8 ani."},{"id":"B","text":"Debutul rizalizei la caninii temporari are loc în jurul vârstei de 8 ani."},{"id":"C","text":"Debutul rizalizei la incisivii temporari se produce la vârsta de 4-5 ani."},{"id":"D","text":"Existența canalelor de comunicare la nivelul furcației determină o osteoscleroză localizată."},{"id":"E","text":"Scurtarea rădăcinii este însoțită de lărgirea orificiului apical."}],"correct":["B","C","E"],"pages":[388],"source":"set-2"},{"id":"set2-arRqoGHd","fingerprint":"f4dfa81b3b5c11f6","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"În contextul relației dintre morfologia dinților temporari și leziunile odontale, care sunt consecințele clinice și patologice specifice?","options":[{"id":"A","text":"Forma globuloasă a coroanelor reprezintă un factor important de protecție împotriva traumatismelor ocluzale."},{"id":"B","text":"Inervația dinților temporari este superioară celei a dinților permanenți, amplificând simptomatologia."},{"id":"C","text":"Există o expunere crescută la deschiderea accidentală a camerei pulpare."},{"id":"D","text":"Caria dentară prezintă o evoluție rapidă."},{"id":"E","text":"Capacitatea reparatorie a pulpei dentare este mult crescută."}],"correct":["A","C","D"],"pages":[388],"source":"set-2"},{"id":"set2-6tUyiTuD","fingerprint":"3b1b9db420ea9dcc","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care modificare structurală reprezintă o caracteristică definitorie a pulpei dentare în stadiul de dinte temporar cu rădăcina în resorbție?","options":[{"id":"A","text":"Creșterea pronunțată a potențialului defensiv și reparator al pulpei."},{"id":"B","text":"Proliferarea semnificativă a elementelor celulare pulpare."},{"id":"C","text":"Reducerea comunicării pulpo-parodontale prin obliterarea canalelor accesorii."},{"id":"D","text":"Vascularizația pulpară foarte bogată ce susține coarnele pulpare superficiale."},{"id":"E","text":"Apariția modificărilor degenerative fibroase și a depunerilor calcare intrapulpare."}],"correct":["E"],"pages":[388],"source":"set-2"},{"id":"set2-7egGmTs-","fingerprint":"f1986a8eeb696c3d","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile corecte referitoare la caria circulară a dinților temporari?","options":[{"id":"A","text":"Incisivii inferiori sunt afectați în mod constant și sever de acest tip de proces carios."},{"id":"B","text":"Extinderea leziunii are loc circular, progresia fiind mai accentuată în suprafață comparativ cu profunzimea."},{"id":"C","text":"Un factor favorizant major este consumul băuturilor îndulcite în timpul somnului, pe fondul scăderii secreției salivare."},{"id":"D","text":"Evoluția este marcată de o progresie accelerată ce culminează cu fracturarea dinților afectați."},{"id":"E","text":"Debutează ca o pigmentație la nivelul coletului, predominant pe fețele palatinale și linguale."}],"correct":["B","C","D"],"pages":[389,390],"source":"set-2"},{"id":"set2-X_eKdyYk","fingerprint":"e9d0c63e66d20c82","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele caracteristici sunt specifice cariei cronice a dinților temporari?","options":[{"id":"A","text":"La nivelul peretelui pulpar, dentina afectată capătă o consistență moale și o colorație deschisă, alb-cretoasă."},{"id":"B","text":"Suprafața dentinară alterată, situată pe peretele pulpar, se prezintă dură și are o nuanță brun-negru."},{"id":"C","text":"Procesul patologic are o evoluție fulminantă, transformarea în carie complicată având loc în 1-2 luni de la debut."},{"id":"D","text":"Deschiderea largă în suprafață și extinderea redusă în profunzime creează condiții favorabile autocurățirii."},{"id":"E","text":"Ritmul lent de evoluție oferă pulpei dentare posibilitatea de a depune cantități mari de dentină de reacție."}],"correct":["B","D","E"],"pages":[389,390],"source":"set-2"},{"id":"set2-gnDsfT5Z","fingerprint":"aad51a691c44b9f5","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În clasificarea morfologică și topografică Black aplicată dinților temporari, care dintre următoarele cavități prezintă o frecvență mai redusă de diagnosticare datorită proceselor de abrazie fiziologică?","options":[{"id":"A","text":"Cavitățile de clasa a V-a, având o localizare exclusivă în treimea cervicală a coroanelor dentare."},{"id":"B","text":"Cavitățile de clasa a IV-a, interesând unghiul incizal la nivelul incisivilor și caninilor."},{"id":"C","text":"Cavitățile de clasa I, localizate pe suprafața ocluzală a molarilor temporari."},{"id":"D","text":"Cavitățile de clasa a II-a, situate pe suprafețele proximale ale molarilor temporari."},{"id":"E","text":"Cavitățile de clasa a VI-a, caracterizate prin afectarea cuspizilor molarilor temporari."}],"correct":["E"],"pages":[389,390],"source":"set-2"},{"id":"set2-ybZi1Eg8","fingerprint":"7f6ffc7aa692f3ca","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt particularitățile cariei oprite în evoluție la nivelul dinților temporari?","options":[{"id":"A","text":"Din punct de vedere chimic, procesele de demineralizare se intensifică și le înlocuiesc pe cele de remineralizare."},{"id":"B","text":"Apariția sa pe suprafețele proximale se bazează pe extracția dintelui vecin și instalarea condițiilor de autocurățire."},{"id":"C","text":"Examenul clinic evidențiază o suprafață de smalț cu o consistență dură, de culoare brună și cu aspect rugos."},{"id":"D","text":"La origine, această leziune a debutat ca o carie acută, evoluția sa fiind stopată ulterior."},{"id":"E","text":"Aspectul clinic o diferențiază net de caria cronică printr-o textură moale și netedă a substratului afectat."}],"correct":["B","C","D"],"pages":[389,390],"source":"set-2"},{"id":"set2-S5xKr1a4","fingerprint":"bad6ddae52656e68","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"În patologia dinților temporari, care afirmații descriu formele de gangrenă și necroză pulpară?","options":[{"id":"A","text":"Gangrena simplă se distinge prin menținerea integrității structurilor de susținere, țesuturile parodontale nefiind afectate."},{"id":"B","text":"Gangrena pulpară presupune mortificarea septică a țesuturilor conținute în camera pulpară și sistemul canalar."},{"id":"C","text":"Necroza pulpară este o entitate definită prin mortificarea septică a țesuturilor endodontice."},{"id":"D","text":"Parodontita apicală acută și parodontita apicală cronică se înscriu în categoria manifestărilor clinice ale gangrenei cu afectare parodontală."},{"id":"E","text":"Gangrena complicată presupune strict o afectare a sistemului endodontic, fără a se înregistra vreo implicare a zonei periapicale."}],"correct":["A","B","D"],"pages":[389,390],"source":"set-2"},{"id":"set2-bNGxlGSF","fingerprint":"a303f7785b689f1e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt manifestările subiective ce pot însoți caria simplă a dinților temporari?","options":[{"id":"A","text":"Apare frecvent sensibilitate la ingestia de alimente dulci."},{"id":"B","text":"Pacientul relatează sensibilitate la contactul cu agenții termici și chimici."},{"id":"C","text":"Copilul poate refuza alimentația în prezența unor leziuni odontale multiple și profunde."},{"id":"D","text":"Sensibilitatea dentară crește pe măsură ce organul pulpar involuează."},{"id":"E","text":"Durerea prezintă un tipar clasic, fiind constantă și de intensitate ridicată."}],"correct":["A","B","C"],"pages":[391],"source":"set-2"},{"id":"set2-xlLBsThQ","fingerprint":"eb5fa613c5f178e4","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"La inspecția suprafețelor dentare în cadrul diagnosticului obiectiv al cariei simple a dinților temporari, se pot identifica următoarele modificări:","options":[{"id":"A","text":"Îndepărtarea dentinei ramolite cu ușurință în straturi, folosind o linguriță Black."},{"id":"B","text":"Cavități „în oglindă” la nivelul suprafețelor ocluzale."},{"id":"C","text":"Prezența unei pete albe cretoase și pierderea translucidității smalțului."},{"id":"D","text":"Colorații brun-negricioase la nivelul fisurilor și fosetelor."},{"id":"E","text":"Creastă marginală subminată asociată eventual cu o papilită pe suprafețele proximale."}],"correct":["C","D","E"],"pages":[391],"source":"set-2"},{"id":"set2-YtES9ErX","fingerprint":"b782c5ec8eb22e51","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care afirmație referitoare la tehnicile de testare clinică (percuție și probe termice) în diagnosticul afecțiunilor dinților temporari este conformă cu datele clinice specifice?","options":[{"id":"A","text":"Percuția paraaxială pozitivă sugerează o pulpită seroasă totală care afectează țesuturile periapicale."},{"id":"B","text":"Percuția este constant pozitivă în caria simplă a dinților temporari."},{"id":"C","text":"Probele termice cu stimuli reci se realizează aplicând clorură de etil la nivelul treimii apicale a dintelui."},{"id":"D","text":"Testele termice cu stimuli calzi utilizează un baton de gutapercă încălzit aplicat în treimea cervicală."},{"id":"E","text":"Percuția axială pozitivă indică în mod exclusiv o patologie de cauză parodontală."}],"correct":["D"],"pages":[391],"source":"set-2"},{"id":"set2-X-c6_1kb","fingerprint":"994bd911e3a67c8d","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Diagnosticul diferențial al cariei simple a dinților temporari impune diferențierea față de următoarele afecțiuni:","options":[{"id":"A","text":"Displaziile dentare, în cazul cariei cronice și cariei acute simple superficiale sau incipiente."},{"id":"B","text":"Cariile complicate cu necroză și gangrenă pulpară, având un proces carios aparent nepenetrant."},{"id":"C","text":"Parodontita apicală acută de cauză iatrogenă."},{"id":"D","text":"Cariile complicate cu pulpite cronice cu camera pulpară deschisă sau închisă."},{"id":"E","text":"Pulpita acută purulentă totală, care prezintă întotdeauna simptomatologie absentă."}],"correct":["A","B","D"],"pages":[392],"source":"set-2"},{"id":"set2-mtjIxX-X","fingerprint":"e5d9a3d599074305","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce condiții sunt necesare pentru a asigura o evoluție pe termen lung adecvată a dinților temporari afectați de caria simplă?","options":[{"id":"A","text":"Efectuarea testelor de vitalitate exclusiv cu probe termice reci."},{"id":"B","text":"Complianța pacientului și a familiei pentru menținerea unui status odonto-parodontal corespunzător."},{"id":"C","text":"Contraindicarea examenului radiologic pe termen lung din cauza riscului de iradiere."},{"id":"D","text":"Aplicarea unui tratament corect și în timp util pentru un prognostic favorabil."},{"id":"E","text":"Controale periodice efectuate la un interval restrictiv de 1 până la 2 luni."}],"correct":["B"],"pages":[392],"source":"set-2"},{"id":"set2-ZramH71E","fingerprint":"7f8b58c158aac2f2","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la criteriile topografice și de vârstă în tratamentul cariei simple a dinților temporari?","options":[{"id":"A","text":"Leziunile odontale localizate la nivelul grupului frontal se vor trata până la vârsta de 7 ani."},{"id":"B","text":"Leziunile localizate la nivelul zonei de sprijin se tratează până la vârste de 10-11 ani."},{"id":"C","text":"După vârsta de 8 ani, se vor trata mai ales molarul doi și caninul temporar superior."},{"id":"D","text":"Conduita terapeutică în cazul cariei simple depinde de vârsta cronologică, dar este independentă de vârsta dentară a pacientului."},{"id":"E","text":"Până la vârsta de 8 ani, conduita terapeutică vizează în exclusivitate molarul doi și caninul temporar superior."}],"correct":["B","C"],"pages":[394],"source":"set-2"},{"id":"set2-cau95ZVY","fingerprint":"fba53a9832a671f8","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele particularități sunt specifice preparării cavităților în tratamentul cariei simple a dinților temporari?","options":[{"id":"A","text":"Pentru cavitățile de clasa a V-a, profunzimea preparării nu trebuie să depășească 1,5-2 mm."},{"id":"B","text":"Pentru cavitățile de clasa I, se pot realiza două cavități ocluzale dacă creasta oblică de smalț este suficient de rezistentă."},{"id":"C","text":"Asigurarea retenției și rezistenței se realizează prin extensia cavității în profunzime, nu în suprafață."},{"id":"D","text":"La prepararea cavităților nu se realizează bizotarea marginilor, ci doar o netezire a acestora."},{"id":"E","text":"În cazul cariilor superficiale care interesează incisivii temporari, se indică aplicarea de rutină a unei coroane pedodontice preformate."}],"correct":["A","B","D"],"pages":[393],"source":"set-2"},{"id":"set2-ZUz95RPe","fingerprint":"cddc0f1b08a805bb","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Referitor la tratamentul cariei simple superficiale la dinții temporari, identificați afirmația corectă:","options":[{"id":"A","text":"Materialele compozite sunt de primă alegere, deoarece necesită criterii de izolare mult mai permisive decât ionomerii de sticlă."},{"id":"B","text":"Îndepărtarea completă a țesuturilor afectate și infectate se verifică prin utilizarea unui indicator de carie."},{"id":"C","text":"Pentru toaleta cavității se utilizează substanțe iritante cu rol de a desensibiliza țesuturile dentare restante."},{"id":"D","text":"Cimenturile glassionomer sunt contraindicate în cazul izolării cu rulouri de bumbac deoarece sunt complet intolerante la umezeală."},{"id":"E","text":"Îndepărtarea procesului carios se realizează cu instrumentar manual pentru a evita zgomotul și a crește complianța pacientului."}],"correct":["B"],"pages":[393],"source":"set-2"},{"id":"set2-ObUvgk2I","fingerprint":"3b75ab007ce96f6b","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele enunțuri descriu deciziile terapeutice la nivelul plăgii dentinare în caria simplă profundă a dinților temporari?","options":[{"id":"A","text":"Tratamentul plăgii dentinare se realizează independent de stadiul evolutiv al dintelui temporar, singurul criteriu fiind aspectul macroscopic al dentinei."},{"id":"B","text":"Coafajul indirect se realizează dacă dentina situată pe baza cavității este dură, normală sau pigmentată, modificările inflamatorii pulpare sunt absente sau limitate, iar dintele se află în stadiul 1 sau 2."},{"id":"C","text":"Orice deschidere accidentală a camerei pulpare în timpul pregătirii cavității la un dinte simptomatic anterior se va trata prin coafaj direct cu hidroxid de calciu."},{"id":"D","text":"Tratamentul endodontic este indicat atunci când dentina de pe baza cavității este dură și normal colorată, dar există suspiciunea afectării integrității organului pulpar."},{"id":"E","text":"Coafajul direct este indicat în cazul deschiderii camerei pulpare la un dinte în stadiul 1, dacă zona de deschidere este limitată, înconjurată de dentină neafectată și se respectă condițiile de izolare."}],"correct":["B","D","E"],"pages":[394],"source":"set-2"},{"id":"set2-1xoWQRFr","fingerprint":"579e8aa1886e2133","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"În vederea reconstituirii morfologiei coronare a molarilor temporari în urma tratamentului cariei profunde, care sunt avantajele utilizării incrustațiilor?","options":[{"id":"A","text":"Evitarea pericolului lezării pulpei dentare."},{"id":"B","text":"Realizarea eficientă a punctelor de contact."},{"id":"C","text":"Necesitatea minimă a unor etape de laborator."},{"id":"D","text":"Reducerea pericolului de fracturare la nivelul istmului."},{"id":"E","text":"Costul scăzut, fiind soluții foarte accesibile pentru aplicarea pe scară largă."}],"correct":["A","B","D"],"pages":[394],"source":"set-2"},{"id":"set2-AcGGvXWO","fingerprint":"0351a7ed9f5c3ae9","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt cauzele frecvente ale apariției cariei complicate a dinților temporari?","options":[{"id":"A","text":"situarea profundă a coarnelor pulpare"},{"id":"B","text":"evoluția lentă a procesului carios spre profunzime"},{"id":"C","text":"folosirea excesivă a turbinei și frezajul neîntrerupt"},{"id":"D","text":"podeaua mai subțire a camerei pulpare"},{"id":"E","text":"dimensiunea redusă a camerei pulpare"}],"correct":["C","D"],"pages":[395],"source":"set-2"},{"id":"set2-DKEsTmeY","fingerprint":"bfee6a046d327a84","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt semnele clinice și simptomele asociate pulpitei acute purulente la dinții temporari?","options":[{"id":"A","text":"în forma purulentă totală este prezentă sensibilitatea și durerea la percuția în ax"},{"id":"B","text":"crizele dureroase se accentuează sau sunt declanșate predominant în timpul nopții"},{"id":"C","text":"la deschiderea camerei pulpare se eliberează puroi, intensitatea durerii crescând treptat ulterior"},{"id":"D","text":"durerea este exacerbată de contactul cu lichidele reci menținute în cavitatea bucală"},{"id":"E","text":"durerea este spontană, având un caracter pulsatil"}],"correct":["A","B","E"],"pages":[396],"source":"set-2"},{"id":"set2-C66tZ-Y6","fingerprint":"70ffe5768fa6a169","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care dintre următoarele elemente reprezintă semnul distinctiv la inspecție în cazul diagnosticului pozitiv al pulpitei dinților temporari?","options":[{"id":"A","text":"mobilitatea dentară pronunțată, cu deplasare axială"},{"id":"B","text":"discromia coronară evidentă, cu tentă gri-albăstruie"},{"id":"C","text":"retracția gingivală marcată, cu expunerea furcației radiculare"},{"id":"D","text":"congestia gingivală la nivelul dintelui afectat"},{"id":"E","text":"formarea unui traiect fistulos pe mucoasa vestibulară"}],"correct":["D"],"pages":[395],"source":"set-2"},{"id":"set2-C1wizinQ","fingerprint":"0e6330add091239a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt caracteristicile clinice specifice pulpitei acute seroase a dinților temporari?","options":[{"id":"A","text":"descoperirea unor depozite bogate de dentină moale în cavitatea carioasă"},{"id":"B","text":"apariția unei picături de puroi la deschiderea unui corn pulpar"},{"id":"C","text":"sensibilitatea accentuată a pulpei dentare la atingere după descoperirea sa"},{"id":"D","text":"prezența unei dureri care este ameliorată constant de lichidele reci"},{"id":"E","text":"ineficiența antialgicelor uzuale în controlul durerii în stadiul de pulpită seroasă totală"}],"correct":["A","C","E"],"pages":[396],"source":"set-2"},{"id":"set2-MctUdl-5","fingerprint":"47517ae63444030e","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații descriu tabloul clinic al pulpitei cronice cu camera pulpară închisă?","options":[{"id":"A","text":"reprezintă o afecțiune pulpară intens asimptomatică în toate cazurile"},{"id":"B","text":"durerea iradiază puternic, fiind declanșată exclusiv de agenți chimici dulci"},{"id":"C","text":"examenul obiectiv evidențiază frecvent obturații vechi cu carie secundară"},{"id":"D","text":"durerea este raportată de pacient ca apărând în timpul masticației"},{"id":"E","text":"se manifestă printr-un disconfort dureros cu un caracter inconstant"}],"correct":["C","D","E"],"pages":[396],"source":"set-2"},{"id":"set2-ND7kAEMA","fingerprint":"7db4f57ab691bee1","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt caracteristicile clinice ale pulpitei cronice cu camera pulpară deschisă în forma granulomatoasă (polipoasă)?","options":[{"id":"A","text":"Polipul pulpar prezintă o sensibilitate extremă la palparea superficială din cauza numeroaselor terminații nervoase."},{"id":"B","text":"Această formă clinică este caracterizată de o cavitate carioasă profundă cu camera pulpară închisă."},{"id":"C","text":"Diagnosticul corect implică identificarea bazei de implantare pentru a exclude confuzia cu un polip gingival."},{"id":"D","text":"La nivelul orificiului de deschidere a camerei pulpare se dezvoltă un polip pulpar lax, roșu și detașabil."},{"id":"E","text":"Simptomatologia subiectivă include disconfort la masticație și sângerare localizată în urma lezării."}],"correct":["C","D","E"],"pages":[397],"source":"set-2"},{"id":"set2-7aF9zdeI","fingerprint":"c3c1e0424cf66736","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele tehnici de tratament se asociază corect cu indicațiile lor în managementul pulpitelor la dinții temporari?","options":[{"id":"A","text":"Amputația vitală (pulpotomia) este indicată în cazul extracțiilor dentare contraindicate."},{"id":"B","text":"Coafajul indirect vizează conservarea pulpei în totalitate și se aplică în cariile profunde la dinții cu rădăcinile în formare."},{"id":"C","text":"Pulpotomia devitală se aplică în carii profunde la pacienții non-complianți sau atunci când izolarea este imposibilă."},{"id":"D","text":"Extracția dentară este de primă intenție atunci când timpul până la exfolierea fiziologică este mai mic de un an."},{"id":"E","text":"Extirparea vitală (pulpectomia) se realizează în pulpitele totale la dinții cu rădăcina formată."}],"correct":["B","C","D","E"],"pages":[398],"source":"set-2"},{"id":"set2-P6VH0yPY","fingerprint":"883a8674329ae42a","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Printre indicațiile de extracție a unui dinte temporar afectat pulpar se numără:","options":[{"id":"A","text":"Resorbțiile radiculare ce cuprind peste 2/3 din rădăcină."},{"id":"B","text":"Dentația mixtă cu înghesuiri."},{"id":"C","text":"Caria penetrantă în planșeu."},{"id":"D","text":"Prezența semnelor clinice de necroză pulpară sau gangrenă."},{"id":"E","text":"Agenezia dintelui succesional."}],"correct":["A","B","C"],"pages":[398],"source":"set-2"},{"id":"set2-Jc-RuBRt","fingerprint":"4fae207c1c86dd40","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce factori generează dificultăți în tratamentul endodontic al pulpitelor la dinții temporari?","options":[{"id":"A","text":"Prezența canalelor radiculare accesorii."},{"id":"B","text":"Înălțimea redusă a camerei pulpare, care asociază un risc major de apariție a perforațiilor."},{"id":"C","text":"Poziționarea facilă a filmului radiologic de către pacientul copil, ceea ce previne suprapunerile."},{"id":"D","text":"Existența comunicării pulpo-parodontale."},{"id":"E","text":"Diagnosticul bazat exclusiv pe teste de vitalitate obiective, independente de colaborarea pacientului."}],"correct":["A","B","D"],"pages":[398],"source":"set-2"},{"id":"set2-Pxc_uPzW","fingerprint":"c1225a035d40fd68","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care dintre următoarele afirmații descrie o diferență obiectivă între forma ulceroasă și cea granulomatoasă a pulpitei cronice deschise?","options":[{"id":"A","text":"Forma ulceroasă presupune confuzia frecventă cu un polip gingival, necesitând identificarea bazei de implantare."},{"id":"B","text":"Forma ulceroasă este însoțită de o cavitate carioasă profundă, în timp ce forma granulomatoasă se dezvoltă pe dinți integri."},{"id":"C","text":"Forma granulomatoasă prezintă un risc major de acutizare dureroasă continuă, aspect neîntâlnit în forma ulceroasă."},{"id":"D","text":"Țesutul din forma ulceroasă sângerează la palpare, în timp ce polipul din forma granulomatoasă nu sângerează la atingere."},{"id":"E","text":"Țesutul de granulație din forma ulceroasă este sensibil la palparea cu sonda, pe când zonele superficiale ale polipului din forma granulomatoasă sunt insensibile."}],"correct":["E"],"pages":[397],"source":"set-2"},{"id":"set2-dRzpudpR","fingerprint":"c854be1b486bbf78","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt indicațiile clinice pentru realizarea coafajului indirect la dinții temporari aflați în stadiul 1 și 2 de evoluție?","options":[{"id":"A","text":"Deschiderea accidentală a camerei pulpare în timpul preparării cavității, în lipsa contaminării salivare."},{"id":"B","text":"Hiperemia pulpară."},{"id":"C","text":"Traumatismele dentare însoțite de deschiderea punctiformă a camerei pulpare."},{"id":"D","text":"Caria profundă acută cu simptomatologie limitată."},{"id":"E","text":"Pulpita seroasă parțială."}],"correct":["B","D","E"],"pages":[399],"source":"set-2"},{"id":"set2-MkBQscgP","fingerprint":"593354be699e90f6","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Ce particularitate tehnică trebuie respectată în faza de exereză a dentinei alterate în cadrul coafajului direct la dinții temporari?","options":[{"id":"A","text":"Exereza dentinei alterate evită complet abordarea peretelui pulpar, bazându-se exclusiv pe materialele bioactive pentru remineralizare."},{"id":"B","text":"Toaleta cavității se efectuează cu hipoclorit de sodiu imediat înaintea abordării peretelui pulpar."},{"id":"C","text":"Se îndepărtează o cantitate redusă de smalț nesusținut, lăsând dentina alterată pe pereții laterali pentru protecția pulpei dentare."},{"id":"D","text":"Abordarea peretelui pulpar se realizează după curățarea pereților laterali ai cavității."},{"id":"E","text":"Îndepărtarea dentinei alterate se realizează inițial la nivelul plafonului camerei pulpare pentru a evalua rapid amploarea expunerii."}],"correct":["D"],"pages":[399],"source":"set-2"},{"id":"set2-OuZaD97V","fingerprint":"53378a326d8ec9f2","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Pentru care dintre următoarele afecțiuni nu se va folosi metoda coafajului direct în tratamentul dinților temporari?","options":[{"id":"A","text":"Deschiderea accidentală de dimensiune redusă în timpul preparării cavității."},{"id":"B","text":"Expunerea pulpei dentare descoperite accidental în absența contaminării cu salivă."},{"id":"C","text":"Caria profundă acută cu simptomatologie limitată."},{"id":"D","text":"Pulpita seroasă parțială."},{"id":"E","text":"Inflamația pulpară de dată recentă, limitată la pulpa coronară."}],"correct":["D"],"pages":[400],"source":"set-2"},{"id":"set2-WIIknTrp","fingerprint":"977816c69878bd9d","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt afirmațiile valabile privind materialele utilizate și criteriile de evaluare postoperatorie în cazul coafajului direct la dinții temporari?","options":[{"id":"A","text":"Succesul metodei este evidențiat radiologic prin apariția unui strat calcificat dedesubtul materialului de coafaj."},{"id":"B","text":"MTA, hidroxidul de calciu și eugenatul de zinc sunt materiale cu proprietăți bioactive care stimulează capacitatea reparatorie a pulpei dentare."},{"id":"C","text":"Materialele aplicate la nivelul expunerii pulpare stimulează depunerea dentinei secundare de reacție."},{"id":"D","text":"Succesul tratamentului implică resorbția fiziologică a materialului de coafaj la nivelul orificiului de deschidere pulpară."},{"id":"E","text":"Toaleta cavității premergătoare aplicării materialului bioactiv se realizează exclusiv cu agenți de demineralizare."}],"correct":["A","B"],"pages":[399],"source":"set-2"},{"id":"set2-2EW6pNjm","fingerprint":"81f9ff51c5f9dfac","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce caracteristici descriu prognosticul și obiectivele tratamentelor prin coafaj la dinții temporari?","options":[{"id":"A","text":"Prognosticul coafajului direct este chestionabil."},{"id":"B","text":"Ambele metode de coafaj au ca obiectiv principal menținerea vitalității pulpare și desfășurarea funcțiilor dintelui temporar."},{"id":"C","text":"Scopul coafajului direct este păstrarea vitalității pulpare chiar și în condițiile în care pulpa este inflamată și infectată cu germeni patogeni."},{"id":"D","text":"Prognosticul coafajului direct este excelent dacă deschiderea camerei pulpare s-a produs concomitent cu o contaminare salivară minoră."},{"id":"E","text":"Coafajul indirect are un prognostic bun dacă tratamentul este aplicat la timpul potrivit și cantitatea de dentină infectată a fost redusă."}],"correct":["A","B","E"],"pages":[399],"source":"set-2"},{"id":"set2-pUhcZh06","fingerprint":"cbae3acda9d96987","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele situații clinice reprezintă indicații pentru realizarea pulpotomiei vitale la dinții temporari?","options":[{"id":"A","text":"Traumatism dentar cu deschiderea camerei pulpare la un dinte aflat în stadiul 1 sau 2."},{"id":"B","text":"Dinte temporar aflat în stadiul 3 evolutiv."},{"id":"C","text":"Dinte temporar cu carie profundă, simptomatică."},{"id":"D","text":"Pacienți copii cu patologie generală asociată."},{"id":"E","text":"Pulpită acută seroasă parțială."}],"correct":["A","C","E"],"pages":[400],"source":"set-2"},{"id":"set2-Wp1_oZEY","fingerprint":"221ff0e6d78c1b7f","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"În cadrul etapei de pregătire și irigare a canalelor radiculare din tehnica pulpectomiei vitale la dinții temporari, se aplică următoarele principii:","options":[{"id":"A","text":"Stabilirea lungimii de lucru se face folosind exclusiv radiografia preoperatorie."},{"id":"B","text":"Manopera se realizează sub irigare permanentă cu hipoclorit de sodiu în concentrație de 2,5-5%."},{"id":"C","text":"Irigarea permanentă se realizează utilizând exclusiv ser fiziologic în condiții de aspirație continuă."},{"id":"D","text":"Uscarea canalului radicular se realizează cu ajutorul buletelor de vată sterile."},{"id":"E","text":"Pregătirea canalelor radiculare necesită pătrunderea cel puțin cu acul Kerr 25 cu 2% conicitate până la nivelul apexului."}],"correct":["B","E"],"pages":[401],"source":"set-2"},{"id":"set2-e0fxqzCF","fingerprint":"7de3e9baa0747ca5","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Referitor la tratamentele devitale (pulpotomia și pulpectomia devitală) aplicate dinților temporari, care dintre afirmațiile de mai jos sunt adevărate?","options":[{"id":"A","text":"Pacientul cooperant reprezintă o contraindicație pentru ambele proceduri devitale."},{"id":"B","text":"Pulpotomia devitală presupune acțiunea unui preparat medicamentos desensibilizant timp de 7-10 zile."},{"id":"C","text":"Preparatul medicamentos aplicat în prima ședință este alcătuit exclusiv dintr-un anestezic local."},{"id":"D","text":"Pulpectomia devitală este recomandată atunci când dintele prezintă o resorbție radiculară mai mare de două treimi."},{"id":"E","text":"Imposibilitatea izolării câmpului operator reprezintă o indicație pentru realizarea pulpotomiei devitale."}],"correct":["A","B","E"],"pages":[402],"source":"set-2"},{"id":"set2-qflWsuIG","fingerprint":"7496fd7fb026d5f5","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"Care dintre următoarele opțiuni reprezintă o indicație directă pentru efectuarea pulpectomiei vitale la dinții temporari?","options":[{"id":"A","text":"Dinte temporar aflat în stadiul 3 evolutiv cu afectare pulpară."},{"id":"B","text":"Copiii care prezintă patologie generală asociată."},{"id":"C","text":"Hiperemia pulpară la un dinte aflat în stadiul 1 evolutiv."},{"id":"D","text":"Pulpitele totale ale dinților temporari aflați în stadiul 2 evolutiv."},{"id":"E","text":"Prezența resorbțiilor radiculare patologice."}],"correct":["D"],"pages":[401],"source":"set-2"},{"id":"set2-kQEjaP6M","fingerprint":"ed6104a66f8c3081","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt recomandările tehnice corecte pentru realizarea pulpotomiei vitale la dinții temporari?","options":[{"id":"A","text":"Îndepărtarea pulpei coronare se realizează utilizând freze globulare de dimensiune adecvată sau lingurițe Black active."},{"id":"B","text":"Dacă hemoragia este dificil de controlat, se recomandă aplicarea unei bulete cu hipoclorit de sodiu 5%."},{"id":"C","text":"Controlul radiologic pentru aprecierea succesului sau insuccesului metodei se efectuează la un interval de 3 luni."},{"id":"D","text":"La nivelul camerei pulpare evidate se aplică un material bioactiv de tip ZOE cu priză rapidă, hidroxid de calciu peste care se aplică ZOE, sau MTA."},{"id":"E","text":"Hemostaza se obține prin aplicarea compresivă a unei bulete sterile cu ser fiziologic pe fundul cavității timp de 2-3 minute."}],"correct":["A","C","D","E"],"pages":[400],"source":"set-2"},{"id":"set2-3VzPnjT7","fingerprint":"0c34cb23186f3372","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următorii factori sunt implicați în etiologia gangrenei pulpare la dinții temporari?","options":[{"id":"A","text":"Mortificarea aseptică a țesuturilor pulpare"},{"id":"B","text":"Absența totală a fenomenelor de rizaliză radiculară"},{"id":"C","text":"Necrozele pulpare infectate printr-o soluție de continuitate"},{"id":"D","text":"Invazia microbiană directă pe o pulpă sănătoasă consecutiv unui traumatism dentar cu expunere largă"},{"id":"E","text":"Caria profundă a dinților temporari cu deschiderea camerei pulpare"}],"correct":["C","D","E"],"pages":[402],"source":"set-2"},{"id":"set2-6qpiFckX","fingerprint":"5ea2fc1bdf4c71bb","chapterId":"set-2","subchapterId":"set2-5.03","type":"CS","text":"În cadrul tratamentului mecanic conservator al gangrenei dinților temporari, care este conduita terapeutică referitoare la obturația radiculară?","options":[{"id":"A","text":"Utilizarea conurilor de gutapercă pentru a asigura o sigilare apicală completă"},{"id":"B","text":"Obturația treimii apicale a canalului radicular utilizând ciment ionomer de sticlă (CIS)"},{"id":"C","text":"Obturația sistemului endodontic utilizând strict materiale compozite de restaurare"},{"id":"D","text":"Lăsarea permanentă a canalelor radiculare deschise pentru un drenaj optim"},{"id":"E","text":"Obturația radiculară cu hidroxid de calciu cu sau fără iodoform, în absența conurilor de gutapercă"}],"correct":["E"],"pages":[403],"source":"set-2"},{"id":"set2-sumnTKAE","fingerprint":"55bf19f2eedece14","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt elementele anatomice și structurale ce favorizează evoluția rapidă a gangrenei pulpare spre o formă complicată la dinții temporari?","options":[{"id":"A","text":"Comunicarea dintre rădăcini și spațiile interradiculare"},{"id":"B","text":"Procesul de rizaliză a dinților temporari"},{"id":"C","text":"Prezența exclusivă a unei flore microbiene anaerobe"},{"id":"D","text":"Țesutul osos intens și complet mineralizat"},{"id":"E","text":"Țesutul conjunctiv lax"}],"correct":["A","B","E"],"pages":[402],"source":"set-2"},{"id":"set2-2G3_2I_8","fingerprint":"88a6827e199d2992","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele situații patologice și clinice impun decizia terapeutică de extracție a dintelui temporar afectat de gangrenă?","options":[{"id":"A","text":"Existența unor afecțiuni generale ce presupun eliminarea obligatorie a focarelor dentare"},{"id":"B","text":"Menținerea unei funcționalități sporite a dintelui pe arcada dentară"},{"id":"C","text":"Acutizările repetate care periclitează dezvoltarea germenilor dinților permanenți"},{"id":"D","text":"Condițiile ocluzale nefavorabile aplicării menținătorului de spațiu înaintea erupției molarului de 6 ani"},{"id":"E","text":"Prezența unor complicații grave, precum instalarea de abcese repetate"}],"correct":["A","C","E"],"pages":[403],"source":"set-2"},{"id":"set2-VkKiyPUM","fingerprint":"182c7e36d28295d2","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce caracteristici prezintă hipocloritul de sodiu în cadrul tratamentului chimic al afecțiunilor pulpare avansate la dinții temporari?","options":[{"id":"A","text":"Utilizarea sa impune izolarea strictă a dintelui cu sistem de digă"},{"id":"B","text":"Este considerat agentul dezinfectant de elecție"},{"id":"C","text":"Reprezintă materialul ideal pentru obturația radiculară definitivă"},{"id":"D","text":"Deține capacitatea de a neutraliza în totalitate agenții patogeni din sistemul endodontic"},{"id":"E","text":"Poate fi utilizat fără nicio restricție la copiii mici, în absența izolării"}],"correct":["A","B","D"],"pages":[403],"source":"set-2"},{"id":"set2-0ApBGmN_","fingerprint":"6b4ab70bbdff39fe","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt caracteristicile clinice obiective întâlnite în parodontita apicală acută la dinții temporari?","options":[{"id":"A","text":"Proces carios cu camera pulpară deschisă sau aparent închisă."},{"id":"B","text":"Lipsa sensibilității la sondarea camerei pulpare."},{"id":"C","text":"Sensibilitate la percuția în ax."},{"id":"D","text":"Evoluție asimptomatică a leziunii, cu dureri difuze."},{"id":"E","text":"Prezența unei fistule sau a unei zone congestive de 4-5 mm în dreptul zonei apicale."}],"correct":["A","B","C"],"pages":[404],"source":"set-2"},{"id":"set2-_GreUm6s","fingerprint":"7ccc15cf8ceb2cb5","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt aspectele decelabile la examenul radiologic în parodontita apicală acută a dinților temporari?","options":[{"id":"A","text":"Radiotransparență interradiculară care denotă prezența țesutului de granulație."},{"id":"B","text":"Prezența unei fistule cu traiect sinuos în dreptul zonei apicale a dintelui cauzal."},{"id":"C","text":"Stadiul evolutiv al dintelui temporar."},{"id":"D","text":"Gradul de rizaliză, esențial pentru a indica posibilitatea de conservare sau de extracție a dintelui."},{"id":"E","text":"Resorbție interradiculară și/sau apicală extinsă."}],"correct":["C","D","E"],"pages":[404],"source":"set-2"},{"id":"set2-pSimbgha","fingerprint":"3d70509705e02ea2","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care dintre următoarele afirmații descriu corect modelul de exteriorizare a procesului inflamator din parodontita apicală acută la dinții temporari?","options":[{"id":"A","text":"La molarii temporari, exteriorizarea are loc la 2-3 mm sub marginea gingivală, în zona furcației."},{"id":"B","text":"La majoritatea dinților temporari exteriorizarea produce subminarea în totalitate a peretelui osos vestibular."},{"id":"C","text":"La molarii temporari, procesul inflamator se exteriorizează exclusiv la nivelul zonei apicale."},{"id":"D","text":"La incisivi, exteriorizarea se produce la 2-3 mm sub marginea gingivală."},{"id":"E","text":"La incisivi, exteriorizarea procesului inflamator se produce în zona apicală."}],"correct":["A","E"],"pages":[403],"source":"set-2"},{"id":"set2-fM3XrtwT","fingerprint":"153ab1d6132c38c5","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Ce intervenții și măsuri terapeutice fac parte din protocolul de realizare a drenajului endodontic în tratamentul parodontitei apicale acute?","options":[{"id":"A","text":"Menținerea deschisă a dintelui pentru câteva zile, dublată de instruirea pacientului privind igiena."},{"id":"B","text":"Trepanarea apexului urmată de lavajul spațiului endodontic cu soluții dezinfectante."},{"id":"C","text":"Deschiderea sistemului canalar prin abordarea camerei pulpare."},{"id":"D","text":"Extracția dentară sistematică și aplicarea imediată a unui menținător de spațiu inter-dentar."},{"id":"E","text":"Evidarea conținutului canalelor radiculare."}],"correct":["A","B","C","E"],"pages":[404],"source":"set-2"},{"id":"set2-OQLiWZwV","fingerprint":"29e842e08b289853","chapterId":"set-2","subchapterId":"set2-5.03","type":"CM","text":"Care sunt caracteristicile clinice și evolutive specifice parodontitei apicale cronice difuze la dinții temporari?","options":[{"id":"A","text":"În cursul progresiei sale, procesul patologic poate submina peretele osos vestibular în totalitate."},{"id":"B","text":"Evoluția leziunii este predominant asimptomatică, putând asocia dureri difuze, șterse, adesea ignorate."},{"id":"C","text":"Afecțiunea se distinge prin înlocuirea structurilor osoase resorbite cu țesut de granulație."},{"id":"D","text":"Tabloul algic implică dureri de intensitate mare, spontane, cu incapacitatea precizării caracterului lor."},{"id":"E","text":"Instalarea formei cronice se realizează exclusiv ca o consecință obligatorie a cronicizării unui puseu acut."}],"correct":["A","B","C"],"pages":[404],"source":"set-2"}];
